// Batch 29: 512 instead of 256. These tile across a 1635-unit arena floor and
// 260-unit walls, so at 256 a single texel covered a visible patch of ground.
// The drawing routines below all work in a 0..256 space, so the context is
// scaled by 2 and every existing routine gets double the detail for free
// rather than needing its coordinates rewritten.

const SURFACE_TEX_SIZE = 512;

function _canvas() {
    const c = document.createElement('canvas');
    c.width = c.height = SURFACE_TEX_SIZE;
    const g = c.getContext('2d');
    g.scale(SURFACE_TEX_SIZE / 256, SURFACE_TEX_SIZE / 256);
    return g;
}

// --- Derived PBR maps. -----------------------------------------------------
// The arena had colour textures and nothing else, so every surface was
// perfectly smooth: mortar courses, panel seams and cracks were painted on and
// vanished the moment you looked along a wall.
//
// Rather than author twenty more textures by hand, these DERIVE a normal map
// and a roughness map from each existing canvas. That works because the
// authored art already encodes relief as brightness - mortar lines are dark
// because they are recessed, block faces have a light-to-dark gradient because
// they are lit from above - so a Sobel gradient of luminance is a serviceable
// height field. All twenty surfaces gain real relief at once, and each map
// keeps the identity someone hand-drew for it.

function _lumField(canvas) {
    const w = canvas.width, h = canvas.height;
    const d = canvas.getContext('2d').getImageData(0, 0, w, h).data;
    const lum = new Float32Array(w * h);
    for (let i = 0; i < w * h; i++) {
        lum[i] = (d[i * 4] * 0.299 + d[i * 4 + 1] * 0.587 + d[i * 4 + 2] * 0.114) / 255;
    }
    return { lum, w, h };
}

function _normalCanvas(canvas, strength) {
    const { lum, w, h } = _lumField(canvas);
    const out = document.createElement('canvas');
    out.width = w; out.height = h;
    const ctx = out.getContext('2d');
    const img = ctx.createImageData(w, h);
    // Wrapping sample: these textures tile, so the gradient must tile too or a
    // bright seam appears down every repeat boundary.
    const at = (x, y) => lum[(((y % h) + h) % h) * w + (((x % w) + w) % w)];
    for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
            const dx = (at(x - 1, y) - at(x + 1, y)) * strength;
            const dy = (at(x, y - 1) - at(x, y + 1)) * strength;
            const len = Math.hypot(dx, dy, 1);
            const i = (y * w + x) * 4;
            img.data[i]     = ((dx / len) * 0.5 + 0.5) * 255;
            img.data[i + 1] = ((dy / len) * 0.5 + 0.5) * 255;
            img.data[i + 2] = ((1 / len) * 0.5 + 0.5) * 255;
            img.data[i + 3] = 255;
        }
    }
    ctx.putImageData(img, 0, 0);
    return out;
}

function _roughCanvas(canvas, lo, hi) {
    const { lum, w, h } = _lumField(canvas);
    const out = document.createElement('canvas');
    out.width = w; out.height = h;
    const ctx = out.getContext('2d');
    const img = ctx.createImageData(w, h);
    for (let i = 0; i < w * h; i++) {
        // Darker (recessed, dirtier) reads as rougher; bright faces are
        // smoother and catch a highlight. Inverted for that reason.
        const v = Math.max(0, Math.min(1, hi - (hi - lo) * lum[i])) * 255;
        img.data[i * 4] = img.data[i * 4 + 1] = img.data[i * 4 + 2] = v;
        img.data[i * 4 + 3] = 255;
    }
    ctx.putImageData(img, 0, 0);
    return out;
}
// Canvases are cached (the derivation is a per-pixel pass, too slow to repeat),
// but each material gets its OWN THREE texture wrapping the shared canvas so it
// can carry its own `repeat` - a wall, a platform and the floor all tile the
// same source at different densities.

const derivedTextureCache = {};

function _blockWall(g, palette, mortar, detail) {
    g.fillStyle = mortar; g.fillRect(0, 0, 256, 256);
    const rowH = 42, blockW = 84; let row = 0;
    for (let y = 0; y < 256; y += rowH) {
        const off = (row % 2) * (blockW / 2);
        for (let x = -blockW; x < 256; x += blockW) {
            const bx = x + off + 3, by = y + 3, bw = blockW - 6, bh = rowH - 6;
            const ti = ((row * 3 + Math.floor(x / blockW)) % palette.length + palette.length) % palette.length; // guard negative index
            g.fillStyle = palette[ti]; g.fillRect(bx, by, bw, bh);
            const gr = g.createLinearGradient(bx, by, bx, by + bh);
            gr.addColorStop(0, 'rgba(255,255,255,0.07)'); gr.addColorStop(1, 'rgba(0,0,0,0.17)');
            g.fillStyle = gr; g.fillRect(bx, by, bw, bh);
            g.strokeStyle = 'rgba(255,255,255,0.10)'; g.lineWidth = 1.5; g.strokeRect(bx + 1, by + 1, bw - 2, bh - 2);
            g.fillStyle = 'rgba(0,0,0,0.16)'; g.fillRect(bx, by + bh - 3, bw, 3);
            if (detail) detail(g, bx, by, bw, bh);
        }
        row++;
    }
}

