const PHOTO_BASE = AC_ASSET_BASE + 'tex/';   // see shared/roster.js

const _photoSetPromises = {};    // setId -> Promise<{map, nor, orm} | null>

const _photoTiled = {};          // "setId:slot:rx x ry" -> THREE.Texture

// Loads one set's three files. Resolves to null rather than rejecting when a
// file is missing, so a partial or absent assets/tex/ directory degrades to the
// procedural look instead of throwing inside a .then() nobody is watching.

function tiledPhotoTexture(base, setId, slot, rx, ry) {
    if (!base) return null;
    const key = setId + ':' + slot + ':' + rx.toFixed(2) + 'x' + ry.toFixed(2);
    let t = _photoTiled[key];
    if (t) return t;
    t = base.clone();
    t.needsUpdate = true;
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.anisotropy = 8;
    t.encoding = base.encoding;
    t.repeat.set(rx, ry);
    _photoTiled[key] = t;
    return t;
}

// r128's aoMap samples vUv2, NOT vUv (verified in three.min.js:
// `texture2D( aoMap, vUv2 )`). Without a uv2 attribute the AO channel samples
// garbage and the surface goes blotchy - so any geometry receiving the packed
// ORM's AO needs uv2, and for our meshes it is simply a copy of uv.

function ensureUV2(geo) {
    if (!geo || !geo.attributes || !geo.attributes.uv) return;
    if (geo.attributes.uv2) return;
    geo.setAttribute('uv2', geo.attributes.uv);
}

// Swap a photographic set onto a material that is ALREADY rendering with its
// procedural texture. Async by design: see note 1 at the top of this section.
//
// `kind` is 'wall' or 'floor'; `texId` is theme.wallTex / theme.floorTex.

const _accentCanvasCache = {};

const _accentTiled = {};      // "key:emi:RxR" -> THREE.Texture

function accentEmissiveTexture(sourceCanvas, accentHex, key) {
    const cached = _accentCanvasCache[key];
    if (cached !== undefined) return cached;
    let out = null;
    try {
        const w = sourceCanvas.width, h = sourceCanvas.height;
        const src = sourceCanvas.getContext('2d').getImageData(0, 0, w, h);
        const ar = (accentHex >> 16) & 255, ag = (accentHex >> 8) & 255, ab = accentHex & 255;
        const cv = document.createElement('canvas');
        cv.width = w; cv.height = h;
        const ctx = cv.getContext('2d');
        const img = ctx.createImageData(w, h);
        let lit = 0;
        for (let i = 0; i < w * h; i++) {
            const r = src.data[i * 4], g = src.data[i * 4 + 1], b = src.data[i * 4 + 2];
            // Distance in RGB is crude but sufficient here: the accents are
            // saturated and the base palettes are greys and browns, so the
            // two are far apart in any colour space.
            const d = Math.hypot(r - ar, g - ag, b - ab);
            const k = Math.max(0, 1 - d / 92);          // 1 at the accent, 0 well away
            const v = k * k;                            // bias toward the strongest matches
            if (v > 0.02) lit++;
            img.data[i * 4]     = ar * v;
            img.data[i * 4 + 1] = ag * v;
            img.data[i * 4 + 2] = ab * v;
            img.data[i * 4 + 3] = 255;
        }
        // A texture that lights up almost everything is not a signature, it is
        // a mistake - bail rather than make a wall uniformly glow.
        if (lit > w * h * 0.34 || lit < 12) return (_accentCanvasCache[key] = null);
        ctx.putImageData(img, 0, 0);
        out = new THREE.CanvasTexture(cv);
        out.wrapS = out.wrapT = THREE.RepeatWrapping;
        out.encoding = THREE.sRGBEncoding;   // it IS colour, unlike normal/ORM
        out.anisotropy = 4;
    } catch (e) {
        out = null;                          // tainted canvas or no 2d context
    }
    _accentCanvasCache[key] = out;
    return out;
}

// Applies the accent overlay to a material whose `map` is (or was) the
