// The bone's world rotation is parentWorld * boneLocal, so to impose a world
// rotation q the local part becomes inverse(parentWorld) * q * boneWorld.

function _prunePosedComponents(geo, chainPts, radius) {
    const pos = geo.attributes.position;
    const idx = geo.index;
    if (!pos || !idx) return geo;
    const index = idx.array;

    const Q = 1e-4;
    const weld = new Map();
    const rep2 = new Int32Array(pos.count).fill(-1);
    for (let v = 0; v < pos.count; v++) {
        const k = Math.round(pos.getX(v) / Q) + ',' +
                  Math.round(pos.getY(v) / Q) + ',' +
                  Math.round(pos.getZ(v) / Q);
        const hit = weld.get(k);
        if (hit === undefined) { weld.set(k, v); rep2[v] = v; } else { rep2[v] = hit; }
    }
    const par = new Map();
    const find = x => { while (par.get(x) !== x) { par.set(x, par.get(par.get(x))); x = par.get(x); } return x; };
    for (let i = 0; i < index.length; i++) { const r = rep2[index[i]]; if (!par.has(r)) par.set(r, r); }
    const uni = (a, b) => { a = find(a); b = find(b); if (a !== b) par.set(a, b); };
    for (let i = 0; i < index.length; i += 3) {
        uni(rep2[index[i]], rep2[index[i + 1]]);
        uni(rep2[index[i + 1]], rep2[index[i + 2]]);
    }

    // WHICH COMPONENTS TO KEEP, and why this is a size rule rather than a
    // distance one.
    //
    // Four distance-based rules were tried and every one of them kept the
    // fragment: bind-pose bone proximity, a bind-pose chain bounding box, the
    // posed full chain, and the posed forearm. Measuring the result explained
    // it - the piece is a 256-triangle scrap of Draven's tasset that
    // auto-weighting bound to the arm bones, and once the arm is posed it sits
    // roughly a forearm-radius below the wrist. There is no radius that
    // excludes it and still admits a real sleeve.
    //
    // Relative size does separate them cleanly, with a large margin: the
    // fragment is 7% of the arm, while the genuine shells - plate, sleeve,
    // glove - are all a substantial share of it. Anything under a quarter of
    // the largest shell is not a part of the arm at this level of detail. The
    // component holding the HAND is always kept regardless of its size, so the
    // one piece that is guaranteed to be on screen can never be pruned.
    const near = new Set();
    const _v = new THREE.Vector3(), _ab = new THREE.Vector3(), _ap = new THREE.Vector3();
    const distToChain = (x, y, z) => {
        _v.set(x, y, z);
        let best = Infinity;
        for (let i = 1; i < chainPts.length; i++) {
            const a = chainPts[i - 1], b = chainPts[i];
            _ab.subVectors(b, a);
            const denom = _ab.dot(_ab);
            const t = denom <= 1e-12 ? 0 : Math.max(0, Math.min(1, _ap.subVectors(_v, a).dot(_ab) / denom));
            const d = _v.distanceTo(_ap.copy(a).addScaledVector(_ab, t));
            if (d < best) best = d;
        }
        return best;
    };
    const sizes = new Map();
    for (let i = 0; i < index.length; i += 3) {
        const c = find(rep2[index[i]]);
        sizes.set(c, (sizes.get(c) || 0) + 1);
    }
    // Records why it did what it did. A silent early return here cost seven
    // five-minute render cycles to diagnose; the decision is cheap to keep.
    geo.userData.prune = { comps: sizes.size, sizes: [...sizes.values()] };
    if (sizes.size <= 1) { geo.userData.prune.why = 'single component'; return geo; }

    // The component holding the vertex nearest the hand - kept unconditionally.
    const handPt = chainPts[chainPts.length - 1];
    let handComp = null, bestD = Infinity;
    for (let i = 0; i < index.length; i++) {
        const v = index[i];
        const d = _v.set(pos.getX(v), pos.getY(v), pos.getZ(v)).distanceTo(handPt);
        if (d < bestD) { bestD = d; handComp = find(rep2[v]); }
    }
    let largest = 0;
    for (const n of sizes.values()) if (n > largest) largest = n;
    for (const [c, n] of sizes) if (n >= largest * 0.25) near.add(c);
    if (handComp !== null) near.add(handComp);
    geo.userData.prune.largest = largest;
    geo.userData.prune.handComp = handComp;
    geo.userData.prune.handCompSize = sizes.get(handComp) || 0;
    geo.userData.prune.kept = near.size;
    if (!near.size || near.size === sizes.size) {
        geo.userData.prune.why = !near.size ? 'nothing qualified' : 'all components qualified';
        return geo;
    }
    geo.userData.prune.why = 'pruned';

    const kept = [];
    for (let i = 0; i < index.length; i += 3) {
        if (near.has(find(rep2[index[i]]))) kept.push(index[i], index[i + 1], index[i + 2]);
    }
    if (kept.length < 60) return geo;   // never prune the arm away entirely
    geo.setIndex(kept);
    geo.computeVertexNormals();
    geo.computeBoundingBox();
    geo.computeBoundingSphere();
    return geo;
}

function _bakePosedGeometry(skinned, keep) {
    const geo = skinned.geometry;
    const pos = geo.attributes.position;
    if (!pos || typeof skinned.boneTransform !== 'function') return null;

    const remap = new Map();
    const order = [];
    const idx = [];
    for (const v of keep) {
        let n = remap.get(v);
        if (n === undefined) { n = order.length; remap.set(v, n); order.push(v); }
        idx.push(n);
    }
    if (idx.length < 60) return null;

    const out = new THREE.BufferGeometry();
    const positions = new Float32Array(order.length * 3);
    const tmp = new THREE.Vector3();
    for (let i = 0; i < order.length; i++) {
        skinned.boneTransform(order[i], tmp);   // <- the posed position
        positions[i * 3] = tmp.x;
        positions[i * 3 + 1] = tmp.y;
        positions[i * 3 + 2] = tmp.z;
    }
    out.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    // Carry UVs and vertex colours; they are pose-independent.
    for (const name of ['uv', 'uv2', 'color']) {
        const attr = geo.attributes[name];
        if (!attr) continue;
        const it = attr.itemSize;
        const dst = new Float32Array(order.length * it);
        for (let i = 0; i < order.length; i++) {
            const src = order[i] * it;
            for (let c = 0; c < it; c++) dst[i * it + c] = attr.array[src + c];
        }
        out.setAttribute(name, new THREE.BufferAttribute(dst, it, attr.normalized));
    }
    out.setIndex(idx);
    out.computeVertexNormals();
    out.computeBoundingBox();
    out.computeBoundingSphere();
    // The cut at the shoulder is a hole - the arm is a slice through a closed
    // mesh - so at some angles you see into the interior. Same defect as the
    // Batch 34 open-ended bracer, on extracted geometry instead of a primitive.
    out.userData.needsCap = true;
    return out;
}

// Closes the open end left by slicing an arm out of a body.
//
// Rather than reconstruct the boundary edge loop and triangulate it - fiddly,
// and the loop is not necessarily planar or even single - this renders the
// inside of the mesh as well. BackSide on a second material means the far wall
// of the tube is drawn instead of culled, so looking into the cut shows the
// arm's own interior surface rather than the skybox through a hole.
//
// It costs one extra draw call for the arm and no geometry work at all, and it
// is robust to whatever shape the cut happens to be - which a triangulated cap
// would not be.

function buildViewmodelArm(f) {
    const g = new THREE.Group();
    const mats = [];
    const skin = makeMat('#c69c78', { roughness: 0.78, metalness: 0.0 });
    const plate = makeMat(f.color, { roughness: 0.42, metalness: 0.65 });
    const trim = darkMetalMat('#242a34');

    // Forearm, tapering from elbow (back, +Z) toward the wrist.
    //
    // Batch 34: LONGER than it needs to be on purpose. The holder sits at
    // z = -12 scaled 0.30, so the elbow end lands around z = -9 in camera
    // space - in front of the near plane and pointed straight at the viewer.
    // At the old length the limb simply STOPPED there, in mid-air, which is
    // what made it read as detached: a real first-person arm continues past
    // the edge of the frame. Running it back to z = 16 pushes the far end out
    // of view so the arm reads as attached to a body you cannot see.
    const fore = new THREE.Mesh(
        getCachedGeometry('vmFore2', () => new THREE.CylinderGeometry(1.5, 2.2, 16, 14)),
        skin);
    fore.rotation.x = Math.PI / 2;
    fore.position.set(-0.6, -1.4, 6.4);
    g.add(fore);
    mats.push(skin);

    // Bracer over the forearm, with a rim at the elbow end.
    //
    // Batch 34: the trailing `true` here was `openEnded`, and it was the actual
    // reported defect - "the arm of the character is detached from the body in
    // first person, you can see the back of the block". An open-ended cylinder
    // has no end caps, so with default FrontSide culling the far interior wall
    // is discarded and you look straight through the tube to the background.
    // The elbow end being the nearest part of the model to the camera made it
    // the first thing you saw. Closed now, and it overlaps the forearm along
    // its whole length so the two read as one limb rather than two abutting
    // solids.
    const bracer = new THREE.Mesh(
        getCachedGeometry('vmBracer2', () => new THREE.CylinderGeometry(2.1, 2.45, 8.4, 14)),
        plate);
    bracer.rotation.x = Math.PI / 2;
    bracer.position.set(-0.6, -1.4, 7.4);
    g.add(bracer);
    const rim = new THREE.Mesh(
        getCachedGeometry('vmRim', () => new THREE.TorusGeometry(2.4, 0.34, 6, 14)),
        trim);
    rim.position.set(-0.6, -1.4, 11.2);
    g.add(rim);

    // Glove: palm block plus knuckle plates, angled as a closed grip.
    const palm = new THREE.Mesh(
        getCachedGeometry('vmPalm', () => new THREE.BoxGeometry(3.3, 3.0, 3.4)),
        plate);
    palm.position.set(-0.3, -1.2, 0.2);   // overlaps the forearm's wrist end (B34)
    palm.rotation.y = 0.18;
    g.add(palm);
    const knuckleGeo = getCachedGeometry('vmKnuckle', () => new THREE.SphereGeometry(0.62, 8, 6));
    for (let i = 0; i < 4; i++) {
        const k = new THREE.Mesh(knuckleGeo, trim);
        k.position.set(-1.5 + i * 0.85, 0.25, -0.7);
        g.add(k);
    }
    // Thumb, wrapped over the grip - the cue that reads as "a hand holding it".
    const thumb = new THREE.Mesh(
        // NOT `new THREE.CapsuleGeometry ? ...` - that constructs before it
        // tests, and CapsuleGeometry does not exist until three r140.
        getCachedGeometry('vmThumb', () => new THREE.CylinderGeometry(0.55, 0.5, 2.4, 8)),
        skin);
    thumb.rotation.set(1.15, 0, 0.5);
    thumb.position.set(1.1, -1.0, 0.5);
    g.add(thumb);
    mats.push(plate, trim);

    g.userData.mats = mats;
    return g;
}

function viewmodelAnimKind(atkType) {
    if (atkType === 'dagger') return 'stab';
    if (atkType === 'hammer') return 'overhead';
    if (atkType === 'punch') return 'jab';
    if (atkType === 'bolt' || atkType === 'shard' || atkType === 'orb') return 'cast';
    return 'swing'; // slash / scythe / whip
}

const _vmLerp = (a, b, t) => a + (b - a) * t;

const PROP_OFFSET_MAX = 6;

function armsOf(f) {
    return Array.isArray(f.mesh.userData.weaponArm) ? f.mesh.userData.weaponArm : [f.mesh.userData.weaponArm];
}
// Each special gets its own, more elaborate motion than the basic attack —
// keyed by the character's `special` id (see initMesh setting specialAnim).

const SWING_MAX_FWD = 95, SWING_MAX_BACK = 80;
// How far back a wind-up may go, as a fraction of the strike it precedes.

const SWING_BACK_FRAC = 0.5;

const _swingAxis = new THREE.Vector3(), _swingQ = new THREE.Quaternion(), _swingInv = new THREE.Matrix4();

// Swings one arm `deg` degrees forward, about the axis that actually points
// sideways out of this fighter's body.
//
// NOT about the bone's local X, which is what this did until Batch 46. That
// came from a real measurement - Batch 25 checked that local Z was world +Y on
// both sides, making local X the fore/aft axis - but it was a measurement of
// the OLD rig, whose arm bones all ran along world X. Batch 43 re-rigged every
// character with bones that follow the traced arm: angled down and out, with
// whatever roll Blender derived from that direction. A local-X rotation then
// sweeps a tilted plane, which on Gorgonok's wide shoulders put his fist
// BEHIND him - reported twice.
//
// A direction cannot drift like that. The body's own lateral axis is local +Z
// of the fighter's mesh group (local +X is forward by this file's convention),
// and transforming it into the bone's parent space gives an axis that means
// "swing forward" for any bone, any roll, any character.

function _swingArm(a, deg, f) {
    const b = a.pivot;
    if (!b.userData.swingRest) b.userData.swingRest = b.quaternion.clone();
    if (!deg) { b.quaternion.copy(b.userData.swingRest); return; }
    const body = (f && f.mesh) ? f.mesh : (b.parent || b);
    body.updateWorldMatrix(true, false);
    b.parent.updateWorldMatrix(true, false);
    _swingInv.copy(b.parent.matrixWorld).invert();
    _swingAxis.set(0, 0, 1)
        .transformDirection(body.matrixWorld)
        .transformDirection(_swingInv)
        .normalize();
    // Clamped, because past about 95 degrees a forward swing stops reaching:
    // the hand passes its highest point and comes back toward the body, so
    // `fwdDeg: 105` measured LESS forward travel than a 60-degree wind-up
    // measured backward - which is Nyx, and reads exactly like the swing going
    // the wrong way. Authoring beyond this range asks the shoulder for motion
    // it cannot express.
    deg = Math.max(-SWING_MAX_BACK, Math.min(SWING_MAX_FWD, deg));
    // POSITIVE = FORWARD, which is what every caller means: `fwdDeg: 115`,
    // `reachDeg: 95`, `+150 * strike`. Measured rather than assumed, and the
    // first version had it backwards - +60 degrees put Gorgonok's fist 16
    // units BEHIND his shoulder and -60 put it 17 in front. That sign is the
    // whole of "gorgonok's attack swings behind him", and it was not his
    // animation: every character on the roster struck backwards.
    _swingQ.setFromAxisAngle(_swingAxis, deg * DEG);
    b.quaternion.copy(b.userData.swingRest).premultiply(_swingQ);
}

function _applyArms(arms, deg, f) {
    for (const a of arms) {
        if (!a || !a.pivot) continue;
        if (a.axis === 'x') _swingArm(a, deg, f);
        else a.pivot.rotation.z = a.pivot.userData.restRotZ + deg * DEG;
    }
}

// The fast jab/reach loops used to assign pivot.rotation.z directly, which is
// the swing axis for a procedural arm (a Group hanging from a shoulder) and
// NOT for a skeleton - so on a rigged character the smooth sine below came out
// as a sideways twitch. That is the "snap that doesn't have a smooth
// animation" reported for Ignis, whose whole kit is this animation.

function _reachArms(arms, degs, f) {
    arms.forEach((a, i) => {
        if (!a || !a.pivot) return;
        if (a.axis === 'x') _swingArm(a, degs(i), f);
        else a.pivot.rotation.z = a.pivot.userData.restRotZ + degs(i) * DEG;
    });
}

function _castCharge(chargeOrb, f, wind, strike, poseGain) {
    if (!chargeOrb) return;
    let c = 0;
    if (f.atkState === 'startup') c = wind;
    else if (f.atkState === 'active') c = 1;
    else c = poseGain * 0.5;
    if (c <= 0.02) { chargeOrb.visible = false; return; }
    chargeOrb.visible = true;
    chargeOrb.material.opacity = 0.5 * c + (f.atkState === 'active' ? 0.35 * Math.abs(Math.sin(strike * Math.PI * 4)) : 0);
    chargeOrb.scale.setScalar(0.6 + c * 1.9);
}

// --- Combat effect meshes: ground-projected rings/streaks rather than
// literal 3D recreations of each 2D arc. Position/size are computed once
// at creation from the same e.* fields doBasicAttack()/doSpecial()
// already produce; only opacity/scale animate per frame (see syncEffects). ---

function effectColor(e) {
    const map = { slash: '224,247,255', punch: '255,180,80', hammer: '203,213,225', dagger: '45,212,191',
        scythe: '196,181,253', whip: '134,239,172', fist: '252,165,80' };
    return e.color || map[e.type] || '255,255,255';
}

