const ROUNDS_TO_WIN = 2;

const MAX_ROUNDS = 5; // hard cap so repeated double-KO draws (which advance no one) can't run best-of-3 forever

const GRACE_PERIOD = 40;        // seconds the arena stays full-size before the first collapse tick

const SHRINK_INTERVAL = 18;     // seconds between each collapse tick after the grace period

const CRUSH_AT_FRAC = 0.8;

function inZone(f) {
    const cx = f.x + f.width / 2, cy = f.y + f.height / 2;
    return Math.hypot(cx - ARENA_CX, cy - ARENA_CY) <= ZONE_RADIUS;
}

