// ---- THE LOADING SCREEN --------------------------------------------------
// Implemented from the design canvas; the markup and styles are above. What
// matters here is the ORDER: show, let the browser actually paint, and only
// then do the work that stalls.
//
// A shader compiles the first time its material is drawn, with the scene's
// light count and shadow setup baked in - so the first of everything landed
// mid-fight and froze the frame. Measured at 9,858ms for a first projectile.
// Nothing about that cost changes; it simply happens here now, where a pause is
// what the player expects.
function afterPaint(fn) {
    requestAnimationFrame(() => requestAnimationFrame(() => fn()));
}

// Every texture set this theme will use, settled. Resolves immediately when they
// are already cached, which is every arena after the first visit.
function busyWhile(el, promise, label) {
    let shown = false;
    const timer = setTimeout(() => { shown = true; busy(el, true, label); }, BUSY_DELAY_MS);
    const done = () => { clearTimeout(timer); if (shown) busy(el, false); };
    return Promise.resolve(promise).then(v => { done(); return v; },
                                         e => { done(); throw e; });
}

