// everything that must handle a crowd iterates `coopEnemies`.
let coopResultText = '';

function liveEnemies() { return coopEnemies.filter(e => e && e.hp > 0); }

// ---------------------------------------------------------------------------
// Batch 42: WHO OWNS THE CO-OP ENEMIES.
//
// Offline, and for the host, nobody else does: the enemies are simulated
// locally like any other fighter. Online, the guest must NOT run them - two
// independent copies of the same AI, stepped with each machine's own `dt`,
// diverge immediately and then disagree about who is being hit and whether the
// wave is clear.
//
// So: the host owns spawning, AI, movement and hp; it broadcasts enemy state at
// the same rate it broadcasts its own fighter, and the guest applies it. The
// guest's own attacks still land - it sends a HIT_ENEMY the way it already
// sends a HIT for the opponent (attacker-authoritative), and the host applies
// the damage so the hp that comes back is the one both machines agree on.
//
// `coopIsPuppet()` is the single question every enemy code path asks.

// Zone Control. The ring sits at arena center — which is also where Arena
// Collapse converges, so the shrinking walls naturally squeeze both fighters
// toward the contested point instead of fighting the mode.
const WAVE_HEAL_PCT = 0.30;

// --- Batch 13: the "unlock everything" override. Two entry points (a typed
// cheat code, and a Settings toggle) that both land on this one setter.
//
// Crucially this NEVER writes into `progression` — it's a separate flag the
// accessors above read, so flipping it off restores the real save exactly as
// it was, with every coin and purchase intact. That's the whole reason it's
// an override layer rather than "just grant everything."
let cheatBuffer = '';

// === Batch 10: Audio — everything synthesized with WebAudio, no sample
// files (per the brief's own ground rules). Three gain stages (master ->
// sfx/music) so the volume UI below can control sfx and music
// independently, both still gated by the master fader/mute. AudioContext
// is only constructed on the first user gesture (autoplay policies block
// it otherwise, and constructing it eagerly would also just throw in some
// browsers) — see unlockAudio() below.
function saveAudioSettings() { safeLSSet(AUDIO_SETTINGS_KEY, JSON.stringify(audioSettings)); }

function unlockAudio() {
    initAudio();
    if (actx && actx.state === 'suspended') actx.resume();
}
// Keyboard's first-gesture audio unlock lives in the single keyboard
// dispatcher (C2, kbAudioUnlocked gate); pointer needs its own one-shot.
window.addEventListener('pointerdown', unlockAudio, { once: true });

function refreshAudioUI() {
    document.getElementById('vol-master').value = audioSettings.master;
    document.getElementById('vol-sfx').value = audioSettings.sfx;
    document.getElementById('vol-music').value = audioSettings.music;
    setOptState('btn-audio-mute', audioSettings.muted ? 'On' : 'Off', audioSettings.muted);
    // ...and the numbers the sliders never showed.
    for (const slot of ['master', 'sfx', 'music']) {
        const out = document.getElementById('vol-' + slot + '-value');
        if (out) out.textContent = Math.round((audioSettings[slot] != null ? audioSettings[slot] : 1) * 100) + '%';
    }
}
// The readout has to follow the drag, or the number is only right until you
// touch it. refreshAudioUI writes the slider positions too, which is harmless
// here - they are already where the drag put them.
for (const slot of ['master', 'sfx', 'music']) {
    document.getElementById('vol-' + slot).addEventListener('input', e => {
        audioSettings[slot] = parseFloat(e.target.value);
        applyAudioSettings();
        saveAudioSettings();
        refreshAudioUI();
    });
}
document.getElementById('btn-audio-mute').addEventListener('click', () => {
    audioSettings.muted = !audioSettings.muted;
    applyAudioSettings();
    saveAudioSettings();
    refreshAudioUI();
});

// --- Low-level synth primitives ---
// A short, percussive tone: linear attack then exponential decay to
// near-silence, with an optional pitch sweep (freqEnd) — covers most of
// the game's punchy one-shot cues (impacts, stings, chimes) without
// needing a sample library.
function synthNoise(duration, opts = {}) {
    if (!actx) return;
    const now = actx.currentTime;
    const size = Math.max(1, Math.floor(actx.sampleRate * duration));
    const buffer = actx.createBuffer(1, size, actx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < size; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / size);
    const src = actx.createBufferSource();
    src.buffer = buffer;
    const g = actx.createGain();
    g.gain.value = opts.peak != null ? opts.peak : 0.25;
    let tail = src;
    if (opts.filterFreq) {
        const filter = actx.createBiquadFilter();
        filter.type = opts.filterType || 'lowpass';
        filter.frequency.value = opts.filterFreq;
        src.connect(filter);
        tail = filter;
    }
    tail.connect(g);
    g.connect(opts.bus || sfxGain);
    src.start(now);
}

// --- Gameplay sound effects ---
// Each character's basic weapon maps to one of the same slash/punch/
// hammer/dagger visual-effect identities already used by createEffectMesh
// (plus shard/orb for the two ranged casters) — reused here as a sound
// identity too, so impact/whiff timbre matches what's on screen.
const IMPACT_SFX = {
    slash: (pitch, peak) => { synthTone(520 * pitch, 0.12, { type: 'triangle', freqEnd: 260 * pitch, peak: peak * 0.5 }); synthNoise(0.08, { peak: peak * 0.3, filterFreq: 3000, filterType: 'highpass' }); },
    punch: (pitch, peak) => { synthTone(140 * pitch, 0.14, { type: 'sine', freqEnd: 60 * pitch, peak: peak * 0.7 }); synthNoise(0.07, { peak: peak * 0.4, filterFreq: 800, filterType: 'lowpass' }); },
    hammer: (pitch, peak) => { synthTone(90 * pitch, 0.22, { type: 'sine', freqEnd: 40 * pitch, peak: peak * 0.8 }); synthNoise(0.14, { peak: peak * 0.5, filterFreq: 500, filterType: 'lowpass' }); },
    dagger: (pitch, peak) => { synthTone(900 * pitch, 0.07, { type: 'triangle', freqEnd: 500 * pitch, peak: peak * 0.4 }); synthNoise(0.05, { peak: peak * 0.35, filterFreq: 5000, filterType: 'highpass' }); },
    shard: (pitch, peak) => { synthTone(1100 * pitch, 0.1, { type: 'sine', freqEnd: 700 * pitch, peak: peak * 0.45 }); synthNoise(0.06, { peak: peak * 0.25, filterFreq: 4000, filterType: 'highpass' }); },
    orb: (pitch, peak) => { synthTone(680 * pitch, 0.16, { type: 'sine', freqEnd: 900 * pitch, peak: peak * 0.4 }); },
    scythe: (pitch, peak) => { synthTone(360 * pitch, 0.16, { type: 'sawtooth', freqEnd: 150 * pitch, peak: peak * 0.45 }); synthNoise(0.1, { peak: peak * 0.3, filterFreq: 2200, filterType: 'bandpass' }); },
    bolt: (pitch, peak) => { synthTone(1500 * pitch, 0.09, { type: 'square', freqEnd: 400 * pitch, peak: peak * 0.35 }); synthNoise(0.07, { peak: peak * 0.4, filterFreq: 6000, filterType: 'highpass' }); },
    whip: (pitch, peak) => { synthTone(700 * pitch, 0.06, { type: 'triangle', freqEnd: 1400 * pitch, peak: peak * 0.4 }); synthNoise(0.05, { peak: peak * 0.35, filterFreq: 4500, filterType: 'bandpass' }); }
};

function sfxImpact(charName, damage) {
    const type = SFX_TYPE_BY_CHAR[charName] || 'punch';
    const pitch = 1 - Math.min(0.35, damage / 90); // heavier hits pitch down a bit — reads as "weightier"
    const peak = Math.min(1, 0.5 + damage / 60);
    (IMPACT_SFX[type] || IMPACT_SFX.punch)(pitch, peak);
}

function sfxWhiff() {
    synthNoise(0.12, { peak: 0.15, filterFreq: 1800, filterType: 'bandpass' });
}

function sfxCollapseTick() {
    synthNoise(0.3, { peak: 0.3, filterFreq: 300, filterType: 'lowpass' });
    synthTone(70, 0.35, { type: 'square', peak: 0.2 });
}

function sfxKO() {
    synthNoise(0.4, { peak: 0.35, filterFreq: 400, filterType: 'lowpass' });
    synthTone(120, 0.5, { type: 'sawtooth', freqEnd: 30, peak: 0.3 });
}

// --- Three.js scene: an angled arena camera (Power Stone-style) instead
// of a top-down view. All gameplay math below stays entirely in the
// original 2D (x, y) plane; these two helpers are the only bridge into
// 3D world space (x -> X, y -> Z, ground sits at Y = 0). ---
function worldZ(y) { return y - ARENA_CY; }

// The game's own coordinate system (arena bounds, maps, HUD layout) stays
// a fixed 900x500 virtual space (see VIRTUAL_W/VIRTUAL_H) — only the
// canvas's actual pixel resolution and the camera's aspect ratio change
// here, so resizing can't shift hitboxes, map layouts, or HUD positions.
// A real setting, because bloom is the one effect here with a per-frame cost
// that scales with resolution: five extra full-screen-ish passes. Follows the
// HUD-scale button's idiom - a button that states its own current value -
// rather than introducing a checkbox the settings panel has no other use for.
function refreshBloomUI() {
    setOptState('btn-bloom', bloomEnabled ? 'On' : 'Off', bloomEnabled);
}

const scene = new THREE.Scene();

// --- Rendering layers (three.js): each fighter's body is put on its own
// layer so a first-person camera can exclude ITS OWN fighter's body (you
// don't see your own head/torso from inside your head), while still seeing
// the opponent and the environment. Viewmodels (the weapon in your own
// hands) go on a per-player layer only that player's camera renders. ---
const camP2 = makeFpsCamera(LAYER_P2_BODY, LAYER_P2_VM);

// --- Batch 27: the crush cinematic. -------------------------------------
// Arena Collapse used to finish with both fighters squashed in place while
// still in first person, which meant the most dramatic beat in the match was
// also the one you could see least: your own body is hidden from your own
// camera, so you watched a static wall texture while your health drained.
//
// Now, the moment the walls slam shut, both players leave first person and get
// a side-on third-person shot of themselves pinned between two grinding slabs
// - each player framed in their own half of the screen. Requested, with a
// drawing: two figures side by side, a wall closing on each from both sides.
let crushTime = 0;

const CRUSH_DUST_COUNT = 18;

function crushGap() {
    // Ease-out: the slabs rush in, then grind the last few units slowly, which
    // reads as weight rather than a linear slide.
    const t = Math.min(1, crushTime / 165);
    const eased = 1 - Math.pow(1 - t, 2.4);
    return CRUSH_GAP_START + (CRUSH_GAP_END - CRUSH_GAP_START) * eased;
}

// A side-on shot of one fighter pinned between their slabs, looking down the
// arena Z axis so the walls close horizontally ACROSS the screen - the framing
// the request drew.
function positionCrushCamera(cam, f, dt) {
    const cx = f.x + f.width / 2, cy = f.y + f.height / 2;
    const tx = worldX(cx), tz = worldZ(cy);
    // Ease from the fighter's own eye out to the wide shot, so leaving first
    // person is a camera move rather than a hard cut.
    const t = Math.min(1, crushTime / CRUSH_CAM_IN);
    const ease = 1 - Math.pow(1 - t, 3);
    // 120 units out frames the fighter plus both slabs; further back and the
    // slab faces dominate and the figure reads as a doll in a corridor.
    // Wide enough for two stages plus their slabs when staged; the original
    // 120 when it is one fighter.
    const dist = 34 + 86 * ease;
    cam.position.set(tx, f.z + EYE_HEIGHT + 10 * ease, tz + dist);
    // Rising shake, peaking as the slabs bite.
    const shake = (REDUCED_MOTION ? 0.2 : 1) * (1.5 + 6.5 * ease);
    cam.position.x += (Math.random() - 0.5) * shake;
    cam.position.y += (Math.random() - 0.5) * shake * 0.7;
    cam.lookAt(tx, f.z + 24, tz);
}

// Swap each camera between first person and the crush shot. During the crush a
// camera must see its OWN fighter (normally hidden) and its own slabs, and must
// NOT draw the first-person weapon viewmodel floating in a third-person frame.
// The VM LAYER stays enabled - the crush slabs live on it - so the viewmodel is
// suppressed by hiding the object instead.
function applyCrushCameraLayers() {
    for (const cam of [camP1, camP2]) {
        const own = cam.userData.ownBody;
        if (own === undefined) continue;
        const other = own === LAYER_P1_BODY ? LAYER_P2_BODY : LAYER_P1_BODY;
        if (crushing) {
            // Split-screen: show MY body and hide the opponent's, so each
            // half is one fighter being crushed alone. Without the second half
            // of that swap both fighters appear in both halves, one behind the
            // other, and it stops reading as "this is happening to me".
            //
            // ONLINE: show BOTH. There is only one view, so hiding the
            // opponent meant the shot contained one character and the other
            // player's death was invisible. They are staged side by side
            // rather than one behind the other, which is
            // what made the split-screen version legible in the first place.
            cam.layers.enable(own);
            cam.layers.disable(other);
        } else {
            cam.layers.disable(own);
            cam.layers.enable(other);
        }
    }
    if (vmP1) vmP1.visible = !crushing;
    if (vmP2) vmP2.visible = !crushing;
}

function positionFpsCamera(cam, f, dt) {
    // Batch 27: the crush takes over the camera entirely (see positionCrushCamera).
    if (crushing) { positionCrushCamera(cam, f, dt); return; }
    // Batch 37: the camera follows the VISUAL position, offset included.
    //
    // This is why "when you use your special there is no animation, just a snap
    // to a new location" survived Batch 34. That batch added a visual lag
    // offset and a motion streak - and applied both to `this.mesh`, which in
    // first person is the one thing you never see. The camera went on reading
    // the raw simulation position, so the entire world still jumped in a single
    // frame; the smear was only ever visible to the OPPONENT.
    //
    // Reading the same offset here means a dash or a blink travels for the
    // player using it. The simulation is still instant, so i-frames, hitboxes
    // and range checks are untouched - it is only where the eye is put.
    const cx = f.x + f.width / 2 + (f.visOffX || 0);
    const cy = f.y + f.height / 2 + (f.visOffY || 0);
    const ex = worldX(cx), ey = f.z + EYE_HEIGHT, ez = worldZ(cy);
    cam.position.set(ex, ey, ez);
    _fwd.set(f.fx, 0, f.fy).normalize();
    // Vertical aim. The intro drop keeps its own hardcoded steep downward tilt
    // (it's a cinematic, not something the player is aiming through); in normal
    // play the look target's height comes from the fighter's own pitch, on top
    // of the small baseline down-tilt that keeps the floor and the weapon
    // viewmodel in frame. LOOK_DIST is the (arbitrary) forward distance the
    // target is placed at, so the vertical offset is tan(pitch) * that.
    const LOOK_DIST = 20;
    const pitchDrop = (gameState === 'INTRO' && !f.introLanded)
        ? -22
        : -4 + Math.tan(f.pitch || 0) * LOOK_DIST;
    cam.lookAt(ex + _fwd.x * LOOK_DIST, ey + pitchDrop, ez + _fwd.z * LOOK_DIST);
    const shakeScale = REDUCED_MOTION ? 0.15 : 1;
    // No shake while paused: the PAUSED branch renders but returns before
    // decayCameraShake, so an unguarded shake would vibrate the frozen frame
    // forever if you paused right after a hit.
    if (cameraShakeMag > 0.05 && gameState !== 'PAUSED') {
        cam.position.x += (Math.random() - 0.5) * cameraShakeMag * 0.5 * shakeScale;
        cam.position.y += (Math.random() - 0.5) * cameraShakeMag * 0.35 * shakeScale;
        cam.position.z += (Math.random() - 0.5) * cameraShakeMag * 0.5 * shakeScale;
    }
}

// Decays the shared hit-shake once per frame (the FPS cameras only READ it,
// so it needs decaying somewhere central rather than inside the old camera
// updater that no longer exists).
function decayCameraShake(dt) {
    if (cameraShakeMag > 0.05) cameraShakeMag *= Math.pow(0.85, dt);
    else cameraShakeMag = 0;
}

// Lighting for the enclosed first-person arena. Every light has all render
// layers enabled (layers.enableAll) because the fighters live on their own
// body layers (1/2) so cameras can hide the viewer's own body — a light
// only illuminates objects sharing an enabled layer with it, so without
// this the fighters would render pitch black.
// Bright outdoor daylight. Every light has all render layers enabled
// (layers.enableAll) because the fighters live on their own body layers
// (1/2) so cameras can hide the viewer's own body — a light only
// illuminates objects sharing an enabled layer with it.
// Batch 45: the ambient/hemi/fill trio came DOWN when the environment map
// became directional. They were tuned against a PMREM of a vertical gradient -
// four sources of nearly directionless light (ambient 0.55 + hemi 0.95 + fill
// 0.85 + a 1.8x env) against a single directional key of 1.75, which is why
// screenshots of every arena showed even, shadowless cardboard. The env does
// that job for real now; keeping the fakes as well just double-counts it.
const ambientLight = new THREE.AmbientLight(0xbfd6f5, 0.18);

const hemiLight = new THREE.HemisphereLight(0xdcefff, 0x6b5a45, 0.42);

// The sun — a strong warm-white directional aimed to match the sun sprite
// in the sky dome, casting crisp shadows across the arena.
const keyLight = new THREE.DirectionalLight(0xfff4e0, 2.1);

// A cool sky-bounce fill from the opposite side to keep shadows from going
// muddy — subtle, just lifts the shadowed faces toward the sky color.
const fillLight = new THREE.DirectionalLight(0xbcd8ff, 0.4);

// --- Per-map visual THEMES. Each map has a distinct palette, wall shape +
// material, floor, column style, sky/time-of-day, lighting and scenery, so
// you can tell which arena you're in at a glance. All are DAYTIME (varying
// from cool clear midday to warm golden hour, never night). ---
function themeFor(map) {
    const base = MAP_THEMES[map.name] || MAP_THEMES['Twin Ramparts'];
    return Object.assign({}, base, { accent: hexNum(map.accent), mapName: map.name });
}

// Rises up to this are walkable on foot; taller is a wall you must jump - see
// resolveTallTerrain(), which reverts the move when the rise is too great.
//
// Batch 38: 30 -> 12. Reported with a screenshot: "when you go towards one of
// those short platforms, instead of hitting it and it blocking you, which it
// should do, you snap up onto it."
//
// That was exactly what the old value did. At 30, a 26-unit `step` - the long
// low blocks across Voltaic Nexus, and waist-high on a 40-unit fighter -
// counted as walkable, so walking into its side instantly raised you 26 units
// with no jump, no animation and no cost. It read as a free elevator, because
// that is what it was.
//
// 12 is not arbitrary: the step heights actually present in MAPS are
// 1, 2, 3, 6, 9, then 18, 22, 26, 28, 30. There is a clean gap between "kerb
// or ramp lip you would not notice" and "block you would put a hand on to
// climb", and 12 sits in it. So ramps and thresholds stay walkable and every
// waist-high block now has to be jumped.
//
// Reachability is the thing this could break, and it is asserted -
// tests/mapscheck.js walks every map and checks that all standable ground can
// still be reached, jumps included.
function groundLevelAt(x, y) {
    let best = 0;
    for (const t of TERRAIN) {
        if (Math.abs(x - t.x) > t.hw || Math.abs(y - t.y) > t.hd) continue;
        let h;
        if (t.type === 'ramp') {
            const lo = t.axis === 'x' ? t.x - t.hw : t.y - t.hd;
            const hi = t.axis === 'x' ? t.x + t.hw : t.y + t.hd;
            const v = t.axis === 'x' ? x : y;
            const frac = Math.max(0, Math.min(1, (v - lo) / (hi - lo)));
            h = t.from + (t.to - t.from) * frac;
        } else {
            h = t.height;
        }
        if (h > best) best = h;
    }
    return best;
}

// --- Theme-aware tileable canvas textures. Each map's theme (see MAP_THEMES)
// picks a wall + floor material so the arenas read as completely different
// places (steel, sandstone, granite, marble, red rock, ice). ---
const derivedCanvasCache = {};

// The procedural canvas, reduced to just its accent-coloured pixels, as an
// emissive overlay. This is what keeps each arena recognisable once a shared
// photographic base is doing the heavy lifting: Voltaic Nexus' glowing seams,
// Molten Foundry's lava cracks and the Colosseum's ivy are all painted in the
// theme accent, and they are the map's signature. Everything that is not close
// to the accent hue becomes black, and black is simply "not emitting".
const wallTextureCache = {};

function addRimEdge(x, z, w, d, accent) {
    const mat = new THREE.MeshStandardMaterial({ color: 0x2e3a59, emissive: accent, emissiveIntensity: 0.3 });
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, 5, d), mat);
    m.position.set(x, 2.5, z);
    m.receiveShadow = true;
    mapGroup.add(m);
    return m;
}

function addCornerGlow(x, z, accent) {
    const group = new THREE.Group();
    const glow = new THREE.Mesh(new THREE.SphereGeometry(4, 8, 8), new THREE.MeshBasicMaterial({ color: accent }));
    glow.position.y = 3;
    group.add(glow);
    const light = new THREE.PointLight(accent, 0.5, 150);
    light.position.y = 20;
    group.add(light);
    group.position.set(x, 0, z);
    mapGroup.add(group);
    return group;
}

// A solid block: short ones read as jump-on cover platforms, tall ones as
// full interior walls (collision is the same). Uses the theme wall texture
// so interior cover matches the perimeter, with a glowing accent-trimmed top.
// BUILD ONE OF EACH PAIR, CLONE THE OTHER.
//
// "The arenas should all have perfect 180 degree rotational symmetry, so that
// both players have the exact same situation for every map."
//
// The map DATA has always been symmetric - symmetrycheck asserts it for all ten
// arenas - but the builders decorate with Math.random(), so two calls for two
// mirrored positions produce two different objects. That is what the report
// "on one side there is a ramp and on the other side there are stairs" was.
//
// So: walk the authored list, build the first of each rotational pair, and
// clone the second with its facing a half-turn further round. A clone shares
// geometry and materials, so this is also cheaper than building both.
//
// `build` is expected to position its result and add it to mapGroup (which is
// what the existing builders do), so the clone is placed and added here. Getting
// that wrong left two of Voltaic Nexus's four pillars built but never in the
// scene.
function buildPairedFromData(list, build) {
    const CX = (ARENA_LEFT + ARENA_RIGHT) / 2, CY = (ARENA_TOP + ARENA_BOTTOM) / 2;
    const built = [];
    for (const item of list) {
        const twin = built.find(b => Math.abs(b.x - (2 * CX - item.x)) < 2
                                  && Math.abs(b.y - (2 * CY - item.y)) < 2);
        let mesh;
        if (twin) {
            mesh = twin.mesh.clone();
            mesh.position.set(worldX(item.x), twin.mesh.position.y, worldZ(item.y));
            mesh.rotation.y = twin.mesh.rotation.y + Math.PI;
            mapGroup.add(mesh);
        } else {
            mesh = build(item);
        }
        built.push({ x: item.x, y: item.y, mesh });
        mapEdgeObjects.push({ mesh, x: item.x, y: item.y });
    }
}

// Solid stair block, floor-to-top — always walkable, no jump required.
function buildStepMesh(t, theme) {
    const group = new THREE.Group();
    const slab = new THREE.Mesh(
        new THREE.BoxGeometry(t.hw * 2, Math.max(6, t.height), t.hd * 2),
        new THREE.MeshStandardMaterial({ color: theme.stepColor, roughness: 0.85 })
    );
    slab.position.y = t.height / 2;
    slab.castShadow = true; slab.receiveShadow = true;
    group.add(slab);

    // A NOSING - the overhanging lip on the front of a real stair tread. On a
    // step this is the whole difference between "a block" and "a stair": the
    // lip catches the light while the riser below it falls into shadow, which
    // is also what makes the step READABLE as something you can walk up.
    group.add(edgeBand(t.hw * 2, t.hd * 2, 3, Math.max(6, t.height) - 1.5, 2.5,
        getCachedMaterial('stepNose:' + theme.id, () => new THREE.MeshStandardMaterial({
            color: theme.capColor, roughness: 0.8,
        }))));

    const trim = new THREE.Mesh(
        new THREE.BoxGeometry(t.hw * 2 + 1.5, 1.5, t.hd * 2 + 1.5),
        new THREE.MeshStandardMaterial({ color: theme.accent, emissive: theme.accent, emissiveIntensity: 0.5, transparent: true, opacity: 0.7 })
    );
    trim.position.y = t.height;
    group.add(trim);

    group.position.set(worldX(t.x), 0, worldZ(t.y));
    mapGroup.add(group);
    return group;
}

// Tilted slab approximating the linear from->to incline groundLevelAt()
// computes for this footprint — always walkable, no jump required.
// Solid stepped support (a handful of stacked blocks tracing the slope)
// plus a thin sloped surface on top, so there's no open gap to see or
// walk through underneath — only a real box primitive is used, since a
// single hand-rolled wedge mesh risks inverted normals I can't preview.
function buildRampMesh(t, theme) {
    const group = new THREE.Group();
    const length = t.axis === 'x' ? t.hw * 2 : t.hd * 2;
    const width = t.axis === 'x' ? t.hd * 2 : t.hw * 2;
    const angle = Math.atan2(t.to - t.from, length);
    const supportMat = new THREE.MeshStandardMaterial({ color: theme.stepColor, roughness: 0.85 });

    const SEGMENTS = 6;
    for (let i = 0; i < SEGMENTS; i++) {
        const segLen = length / SEGMENTS;
        const frac0 = i / SEGMENTS, frac1 = (i + 1) / SEGMENTS;
        const hHi = t.from + (t.to - t.from) * frac1;
        if (hHi <= 1) continue; // near-zero end stays open as the ramp's entry
        const offset = ((frac0 + frac1) / 2 - 0.5) * length;
        const seg = new THREE.Mesh(
            new THREE.BoxGeometry(t.axis === 'x' ? segLen : width, hHi, t.axis === 'x' ? width : segLen),
            supportMat
        );
        if (t.axis === 'x') seg.position.set(offset, hHi / 2, 0);
        else seg.position.set(0, hHi / 2, offset);
        seg.castShadow = true; seg.receiveShadow = true;
        group.add(seg);
    }

    const surface = new THREE.Mesh(
        new THREE.BoxGeometry(length, 4, width),
        new THREE.MeshStandardMaterial({ color: theme.accent, emissive: theme.accent, emissiveIntensity: 0.35, transparent: true, opacity: 0.85 })
    );
    surface.position.y = (t.from + t.to) / 2;
    if (t.axis === 'x') surface.rotation.z = angle; else surface.rotation.x = -angle;
    group.add(surface);

    group.position.set(worldX(t.x), 0, worldZ(t.y));
    mapGroup.add(group);
    return group;
}

const mapGroup = new THREE.Group();

let currentMap = null;

// Arena Collapse tracking (see the constants/logic further down): the actual
// map geometry at the shrinking edges falls away as the boundary sweeps past
// it — "as if it never existed" per the brief. `floorMesh` is scaled/
// repositioned every shrink tick, the four `outerWalls` slide inward, and
// `mapEdgeObjects` (pillars/terrain/platforms/scenery, each tagged with its
// game-space x/y) drop away once outside the current play bounds.
let outerWalls = [];

// Slide + scale the four enclosing walls to the current (possibly shrinking)
// play bounds, so during Arena Collapse the room's walls physically close in.
function syncOuterWalls() {
    const cx = worldX((playLeft + playRight) / 2), cz = worldZ((playTop + playBottom) / 2);
    const xExt = Math.max(1, playRight - playLeft), zExt = Math.max(1, playBottom - playTop);
    // Each wall is a group whose run is its LOCAL X (the left/right groups are
    // rotated 90°), so scaling local X shrinks the run for every side. The
    // group origin sits on the floor (children carry their own heights).
    for (const w of outerWalls) {
        if (w.side === 'left') { w.mesh.position.set(worldX(playLeft), 0, cz); w.mesh.scale.x = zExt / w.baseLen; }
        else if (w.side === 'right') { w.mesh.position.set(worldX(playRight), 0, cz); w.mesh.scale.x = zExt / w.baseLen; }
        else if (w.side === 'top') { w.mesh.position.set(cx, 0, worldZ(playTop)); w.mesh.scale.x = xExt / w.baseLen; }
        else { w.mesh.position.set(cx, 0, worldZ(playBottom)); w.mesh.scale.x = xExt / w.baseLen; }
    }
}

// --- Scenery: decorative + collidable props scattered around the arena so
// it reads as a lived-in place, not an empty box. Braziers, crates, barrels,
// urns and wall banners. Solid props (crates/barrels/urns/braziers) are
// registered as circular OBSTACLES so you actually fight around them, and as
// mapEdgeObjects so they fall away with the arena during collapse. ---
const sceneryFlames = [];

function buildCrate(accent) {
    const g = new THREE.Group();
    const size = 34 + Math.random() * 8;
    const woodMat = getCachedMaterial('crateWood', () => new THREE.MeshStandardMaterial({ color: 0x9c6b3f, roughness: 0.85 }));
    const box = new THREE.Mesh(new THREE.BoxGeometry(size, size, size), woodMat);
    box.position.y = size / 2; box.castShadow = true; box.receiveShadow = true;
    g.add(box);
    // A lid rim, overhanging like every other edge in this pass. It is what
    // makes the crate look assembled rather than solid.
    g.add(edgeBand(size, size, 3.5, size - 1.75, 1.6,
        getCachedMaterial('crateLid', () => new THREE.MeshStandardMaterial({ color: 0x84562f, roughness: 0.85 }))));
    const frameMat = getCachedMaterial('crateFrame', () => new THREE.MeshStandardMaterial({ color: 0x6b4522, roughness: 0.8 }));
    for (const sy of [size * 0.5]) { // corner battens
        for (const [ex, ez] of [[0.5, 0.5], [-0.5, 0.5], [0.5, -0.5], [-0.5, -0.5]]) {
            const batten = new THREE.Mesh(new THREE.BoxGeometry(4, size + 1, 4), frameMat);
            batten.position.set(ex * size, size / 2, ez * size); g.add(batten);
        }
    }
    return g;
}

function buildBarrel(accent) {
    const g = new THREE.Group();
    const h = 36, r = 15;
    // A TURNED profile rather than a tapered cylinder: a barrel bulges at the
    // middle and closes at both ends, and that silhouette is the whole reason
    // you read it as a barrel. Flat-shaded so the 14 facets are staves.
    const woodMat = getCachedMaterial('barrelWood', () => new THREE.MeshStandardMaterial({ color: 0x7a5230, roughness: 0.82, flatShading: true }));
    const body = new THREE.Mesh(lathe([
        [r * 0.78, 0], [r * 0.95, h * 0.16], [r, h * 0.5],
        [r * 0.95, h * 0.84], [r * 0.78, h], [0, h],
    ], 14), woodMat);
    body.castShadow = true; body.receiveShadow = true; g.add(body);
    const bandMat = getCachedMaterial('barrelBand', () => new THREE.MeshStandardMaterial({ color: 0x3f3a33, metalness: 0.6, roughness: 0.4 }));
    for (const by of [h * 0.22, h * 0.78]) {
        const band = new THREE.Mesh(new THREE.CylinderGeometry(r * 1.02, r * 1.02, 3, 14), bandMat);
        band.position.y = by; g.add(band);
    }
    return g;
}

function buildUrn(accent) {
    const g = new THREE.Group();
    const mat = getCachedMaterial(`urnMat:${accent}`, () => new THREE.MeshStandardMaterial({ color: 0xcdbb95, roughness: 0.7, metalness: 0.05 }));
    // One turned profile for the whole amphora - foot, belly, shoulder, neck
    // and lip - instead of a squashed sphere with a cone stuck on top. A single
    // surface also means no seam where the neck used to meet the body.
    const body = new THREE.Mesh(lathe([
        [7, 0], [9, 3], [6, 7], [13, 16], [15.5, 26], [13, 36],
        [8, 41], [7.2, 44], [9.5, 46], [8.6, 47.5], [0, 47.5],
    ], 18), mat);
    body.castShadow = true; body.receiveShadow = true; g.add(body);
    const accMat = getCachedMaterial(`urnAcc:${accent}`, () => new THREE.MeshStandardMaterial({ color: accent, emissive: accent, emissiveIntensity: 0.4 }));
    const ring = new THREE.Mesh(new THREE.TorusGeometry(11, 1.6, 6, 14), accMat);
    ring.rotation.x = Math.PI / 2; ring.position.y = 26; g.add(ring);
    return g;
}

function buildBrazier(accent) {
    const g = new THREE.Group();
    const stoneMat = getCachedMaterial('brazierStone', () => new THREE.MeshStandardMaterial({ color: 0x8a7c60, roughness: 0.9 }));
    const stand = new THREE.Mesh(new THREE.CylinderGeometry(6, 10, 40, 10), stoneMat);
    stand.position.y = 20; stand.castShadow = true; g.add(stand);
    // A turned bowl with a rim and a hollow, so the flame sits IN it rather
    // than on top of a tapered disc.
    const bowl = new THREE.Mesh(lathe([
        [8, 38], [15, 46], [16.5, 50], [14.5, 50], [13, 46.5], [7, 40], [0, 40],
    ], 14), stoneMat);
    bowl.castShadow = true; g.add(bowl);
    const flameMat = new THREE.MeshBasicMaterial({ color: 0xffa53c, transparent: true, opacity: 0.95, fog: false });
    const flame = new THREE.Mesh(new THREE.ConeGeometry(9, 26, 10), flameMat);
    flame.position.y = 60; g.add(flame);
    const light = new THREE.PointLight(0xff9640, 1.1, 340);
    light.position.y = 62; light.layers.enableAll(); g.add(light);
    sceneryFlames.push({ mesh: flame, light, phase: Math.random() * 6.28, baseY: 60 });
    return g;
}

// --- Themed nature/tech props for the non-castle arenas ---
function _makeProp(type, theme) {
    switch (type) {
        case 'barrel': return buildBarrel(theme.accent);
        case 'urn': return buildUrn(theme.accent);
        case 'bush': return buildBush(theme);
        case 'rock': return buildRock(theme);
        case 'boulder': return buildBoulder(theme);
        case 'shard': return buildIceShard(theme);
        case 'pylon': return buildTechPylon(theme);
        default: return buildCrate(theme.accent);
    }
}

function updateScenery(dt) {
    for (const f of sceneryFlames) {
        f.phase += 0.15 * dt;
        const flick = 0.8 + Math.sin(f.phase) * 0.12 + Math.sin(f.phase * 2.7) * 0.06;
        f.mesh.scale.y = flick; f.mesh.scale.x = f.mesh.scale.z = 0.9 + (flick - 0.8) * 0.5;
        f.light.intensity = 0.9 + flick * 0.5;
    }
}

// --- Muzzle flash: a brief bright puff + light at a fighter's weapon tip when
// it fires, so a shot visibly erupts from the weapon in BOTH players' views
// (the shooter also gets a viewmodel flash). Kept as a tiny pooled system so
// rapid fire doesn't churn meshes.
// Inputs are GAME-space (gameX 60..1695, gameY 60..915) + a world height, the
// same convention every call site and every other object uses; the game->world
// conversion (worldX/worldZ, ground at Y=0) happens here. ---
const muzzleFlashes = [];

// Batch 30: HARD CAP. Every pool entry carries a PointLight, and changing the
// number of lights in the scene makes three.js recompile every material's
// shader - a multi-hundred-millisecond stall. An unbounded pool therefore turned
// any sustained stream of flashes into a series of frame spikes. Measured during
// the crush: shader programs went 11 -> 27 and one frame took 2.2 seconds.
// Beyond the cap, recycle the flash closest to expiring instead of allocating.
const MUZZLE_FLASH_MAX = 6;

function updateMuzzleFlashes(dt) {
    for (const mf of muzzleFlashes) {
        if (!mf.active) continue;
        mf.life -= dt;
        const t = Math.max(0, mf.life / mf.maxLife);
        mf.mesh.material.opacity = t;
        mf.mesh.scale.setScalar(0.6 + (1 - t) * 2.2); // pop outward as it fades
        mf.light.intensity = t * 2.4;
        if (mf.life <= 0) { mf.active = false; mf.mesh.visible = false; }
    }
}

