// Batch 24: a special's damage lives in character data (see CHARACTERS) rather
// than as a literal inside its doSpecial case, because the shop and select
// screen now display it — a number in the switch plus a number in the UI would
// have been two copies free to drift apart.
//
// A function DECLARATION, not a const arrow: this is read from doSpecial, which
// can't run before load finishes, but declarations hoist completely and so
// can't join this file's long history of temporal-dead-zone regressions.
const TELEPORT_VIS_MIN = 0;

// Basic bot obstacle avoidance: if a pillar sits close to the straight
// line from (fromX, fromY) toward the desired (dirX, dirY) direction,
// return a lateral push away from it so the bot slides around instead of
// walking straight into the pillar and stalling there.
function steerAroundObstacles(fromX, fromY, dirX, dirY) {
    let steerX = 0, steerY = 0;
    const dlen = Math.hypot(dirX, dirY) || 1;
    const dx = dirX / dlen, dy = dirY / dlen;
    for (const ob of OBSTACLES) {
        const toObX = ob.x - fromX, toObY = ob.y - fromY;
        const proj = toObX * dx + toObY * dy;
        if (proj < 0 || proj > 140) continue; // behind, or too far ahead to matter yet
        const closestX = fromX + dx * proj, closestY = fromY + dy * proj;
        const lateral = Math.hypot(ob.x - closestX, ob.y - closestY);
        if (lateral < ob.r + 30) {
            const perpX = -dy, perpY = dx;
            const side = ((ob.x - fromX) * perpX + (ob.y - fromY) * perpY) < 0 ? 1 : -1;
            steerX += perpX * side;
            steerY += perpY * side;
        }
    }
    return { steerX, steerY };
}

// Batch 8: a floating P1/P2 tag above each fighter's head — the other half
// of mirror-match readability alongside the P2 body tint above. depthTest
// false so it stays legible even when a pillar or the opposing fighter is
// between it and the camera.
function makeNameSprite(text, color) {
    const c = document.createElement('canvas');
    c.width = 128; c.height = 32;
    const ctx = c.getContext('2d');
    ctx.font = announceFont(20, 700);   // the name sprite above a fighter
    ctx.fillStyle = color;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(text, 64, 16);
    const tex = new THREE.CanvasTexture(c);
    const sprite = new THREE.Sprite(new THREE.SpriteMaterial({ map: tex, transparent: true, depthTest: false }));
    sprite.scale.set(36, 9, 1);
    sprite.position.y = 62;
    return sprite;
}

// Batch 8: rim/outline pass. A real screen-space outline needs
// EffectComposer/OutlinePass, which isn't part of the core three.min.js
// build the brief pinned via jsDelivr — pulling those in would mean a
// second external module source, against the brief's "Three.js stays the
// one external dependency" rule. Classic inverted-hull technique instead:
// for every shadow-casting mesh in a fighter's group (the real body/weapon
// parts — rings and props don't cast shadows, so this skips them for
// free), add a slightly-scaled BackSide clone sharing the same geometry.
// Front faces of the real mesh still win the depth test everywhere except
// right at the silhouette edge, which is exactly where a rim should show.
// `opts.color` overrides the derived rim colour and `opts.scale` its thickness.
// Both exist for Batch 17's boss: this shell is an UNLIT MeshBasicMaterial, so
// it renders at flat full brightness regardless of scene lighting, and the
// default (body colour lightened 25%) on a 1.5x-scaled boss with chunky limbs
// produced a thick pale-cream border that swamped the actual stone body and made
// the whole boss read as beige plastic. A dark, tighter rim instead gives it a
// crisp silhouette that holds up on both pale and dark maps.
function addRimOutline(group, colorHex, opts) {
    opts = opts || {};
    const outlineColor = opts.color !== undefined
        ? new THREE.Color(opts.color).getHex()
        : new THREE.Color(colorHex).offsetHSL(0, 0, 0.25).getHex();
    const scale = opts.scale || 1.08;
    const mat = getCachedMaterial(`rimOutline:${outlineColor}`, () => new THREE.MeshBasicMaterial({ color: outlineColor, side: THREE.BackSide }));
    const targets = [];
    // Batch 25: userData.noOutline skips Blender-authored characters. The
    // inverted-hull trick clones a mesh's geometry into a plain Mesh, which for
    // a SkinnedMesh would render an un-skinned shell frozen in the bind pose -
    // and on a 23k-triangle body it would double the vertex count for it. Those
    // characters read clearly on their own, so they simply don't get an outline.
    // A rigged character opts out entirely: `noOutline` is inherited down the
    // subtree, so marking the model root and each weapon holder covers the body
    // and its props in one check.
    const optedOut = o => { for (let n = o; n; n = n.parent) if (n.userData && n.userData.noOutline) return true; return false; };
    group.traverse(node => {
        if (node.isMesh && node.castShadow && !node.isSkinnedMesh && !optedOut(node)) targets.push(node);
    });
    for (const node of targets) {
        const outline = new THREE.Mesh(node.geometry, mat);
        outline.position.copy(node.position);
        outline.rotation.copy(node.rotation);
        outline.scale.copy(node.scale).multiplyScalar(scale);
        node.parent.add(outline);
    }
}

// makeMat lives in shared/props.js, with the materials it makes.

// --- Humanoid rig shared by all six characters: two legs, a torso, a
// head, and two shoulder-pivoted arms (each ending in a hand socket group)
// that weapons attach to and animateWeapon() below swings for attacks.
// Replaces the old per-character abstract bodies (a box/octahedron/sphere
// "body" with a floating weapon prop bolted on) with an actual person-
// shaped silhouette, on request. Local +X is forward, feet at Y=0, same
// convention every other builder/animator in the file already assumes.
// Arms hang straight down (-Y) at rest; rotating a shoulder pivot around
// its local Z axis swings that arm through the X-Y plane — negative
// swings it backward (wind-up), positive swings it forward (strike/raise).
// buildHumanoidBase lives in shared/characters.js, with the bodies it builds.

// Batch 28: the first-person arm.
//
// This used to be one BoxGeometry(3.4, 3.4, 11) - a bare rectangular stick in
// the character's flat body colour. It is on screen every frame of every match,
// so it was the single most-seen piece of art in the game and also the crudest,
// and it looked nothing like the armoured arm the same character has in third
// person now that the bodies are Blender-authored.
//
// It is now an armoured forearm: a tapered limb, a plated bracer with a raised
// rim, an armoured glove with knuckle plates, and a thumb - built to read
// correctly from the one angle a viewmodel is ever seen from. The palette is
// taken from the fighter, and the plates use the same metal materials as the
// rebuilt weapons so the hand and the thing it is holding belong together.

// ===========================================================================
// Batch 36: the first-person arm is CUT FROM THE CHARACTER'S OWN MESH.
//
// Requested as "make the arms for each character in first person view look
// exactly like they do in third-person view, with the same hands and
// everything else". The viewmodel arm was a hand-built assembly of primitives
// - a tapered cylinder, a bracer, a box palm, four sphere knuckles - wearing
// the character's accent colour. That is the best you can do with no model;
// with a real rigged model in memory it is strictly worse than the truth, and
// it means Draven's steel gauntlet and Lyra's sleeve look like the same arm
// painted differently.
//
// So: take the loaded SkinnedMesh, keep only the triangles whose vertices are
// weighted to the weapon-side arm chain, and bake them into a static mesh.
// Static is correct here rather than a compromise: syncViewmodels animates the
// viewmodel by moving and rotating the whole HOLDER, never by posing bones, so
// a skinned arm would cost a skeleton per frame and buy nothing.
//
// The result carries the model's own materials, so the hand, the glove, the
// sleeve and the skin tone are the same objects the opponent sees.
// The bones whose geometry becomes the viewmodel arm.
//
// 'Shoulder' is deliberately NOT in here, and that is the fix for the reported
// "sometimes look separated and weird". The viewmodel poses UpperArm, LowerArm
// and Hand to swing the limb forward into view, and leaves Shoulder at rest -
// it has to, because rotating the shoulder would drag the chest with it. So any
// triangle weighted to Shoulder STAYS IN THE BIND POSE while everything around
// it swings forward, and a pauldron or plate left behind in mid-air is exactly
// what "separated" looked like. No distance or connectivity filter can fix
// that, because the geometry is genuinely arm geometry - it is simply posed by
// a bone we are not moving.
//
// Losing the pauldron costs nothing: in first person the shoulder is behind the
// camera. ARM_POSE_CHAIN is what gets posed; ARM_CHAIN is what gets kept, and
// they are now the same set for exactly this reason.
// HOW THE WEAPON IS HELD, in the hand the arm actually ends in. Yaw turns the
// blade inboard across the frame, pitch lifts the tip, roll tilts the flat of
// the blade toward the light so it reads as a blade rather than a line.
// How far the whole limb is tipped toward the bottom-right corner.
const VM_ARM_ROLL = -0.52;

const VM_PROP_TUNE = {
    // A hammer is turned so its FACE is across the view, not pointing down it,
    // and dropped slightly so the head is not level with the crosshair.
    // yaw 0.34 -> 0.92. Reported as "Draven's weapon is backwards in first
    // person", and measurable: the grip-to-head vector is the only one on the
    // roster pointing OUTBOARD. Every other weapon sweeps inboard across the
    // view - Kaelen -4.8, Nyx -7.1, Thorne -8.2, Voss -2.0, Aurelia -4.8 - and
    // the hammer measured +4.1, off the right edge of the frame.
    //
    // The small yaw was a Batch 46 correction for a real problem (the head was
    // being seen end-on, "a flat disc or washer on a thin stick") and it
    // over-shot: turning the head into view also turned the whole weapon out of
    // it. The roll is what keeps the face across the view, so the yaw can come
    // back up.
    // Measured against the rest of the roster rather than eyeballed. The
    // weapon's own axis, in camera space, should point inboard and into the
    // screen like everyone else's: Kaelen (0.39, 0.61), Nyx (0.38, 0.76),
    // Thorne (0.60, 0.70), Voss (0.39, 0.61), Aurelia (0.44, 0.86). The hammer
    // measured (-0.32, 0.25) with its axis 0.91 straight UP - held vertical and
    // tipped out of frame, which is what "Draven's weapon is backwards in first
    // person" was. At yaw 0.92 / roll 0.55 it measures (0.36, 0.58).
    //
    // The old roll of 1.35 was a real fix for a real thing - the head being
    // seen end-on, "a flat disc or washer on a thin stick" - and it over-shot:
    // rolling that far about the weapon's own axis swings the whole haft
    // upright. The yaw carries the head across the view instead.
    hammer: { yaw: 0.92, pitch: -0.12, roll: 0.55 },
    // A scythe is mostly haft with the blade far out; less yaw keeps the blade
    // in frame rather than swinging it off the left edge.
    scythe: { yaw: 0.72, pitch: -0.22, roll: 0.45 },
    // A whip hangs; rolling it does nothing but hide the coil.
    whip: { yaw: 0.80, pitch: -0.10, roll: 0.10 },
    // An orb or a staff head reads from any angle, so they keep it simple and
    // sit where a caster would actually hold them: up and inboard.
    orb: { yaw: 0.75, pitch: -0.45, roll: 0.0 },
    shard: { yaw: 0.75, pitch: -0.45, roll: 0.0 },
    bolt: { yaw: 0.55, pitch: -0.30, roll: 0.25 },
};

function vmPropAngles(atkType) {
    const t = VM_PROP_TUNE[atkType] || {};
    return {
        yaw: t.yaw != null ? t.yaw : VM_PROP_YAW,
        pitch: t.pitch != null ? t.pitch : VM_PROP_PITCH,
        roll: t.roll != null ? t.roll : VM_PROP_ROLL,
    };
}

const VM_ARM_LENGTH = 30;

const VM_ARM_ANCHOR = new THREE.Vector3(3.6, -2.6, -13.6);

// Which bones count as "the arm". Bone names arrive sanitised by three.js
// (PropertyBinding.sanitizeNodeName strips '.'), so 'UpperArm.L' may be
// 'UpperArmL' - match on prefix rather than on an exact name.
function _armTriangles(skinned, side) {
    const geo = skinned.geometry;
    const pos = geo.attributes.position;
    const skinIndex = geo.attributes.skinIndex;
    const skinWeight = geo.attributes.skinWeight;
    if (!pos || !skinIndex || !skinWeight || !skinned.skeleton) return null;
    const armBones = _armBoneIndices(skinned.skeleton, side);
    if (!armBones.size) return null;

    // A vertex belongs to the arm when MOST of its weight does. Using "any
    // weight at all" drags in half the chest, because auto-weighting bleeds a
    // little shoulder influence a long way down the torso.
    // getX/getY/getZ/getW, NOT getComponent(v, k): getComponent does not exist
    // on BufferAttribute in three r128 (it was added later), and calling it
    // throws rather than returning undefined.
    const GET = ['getX', 'getY', 'getZ', 'getW'];
    const isArm = new Uint8Array(pos.count);
    for (let v = 0; v < pos.count; v++) {
        let armW = 0, total = 0;
        for (let k = 0; k < 4; k++) {
            const w = skinWeight[GET[k]](v);
            if (!(w > 0)) continue;
            total += w;
            if (armBones.has(skinIndex[GET[k]](v))) armW += w;
        }
        // 0.8, not 0.6. Automatic weighting is a smooth field, so the
        // shoulder bone bleeds influence a long way down the torso - at 0.6 a
        // patch of Draven's hip cleared the bar and came along as a floating
        // shard. True arm vertices are weighted almost entirely to arm bones,
        // so the threshold can be strict without losing anything real; the
        // bone-proximity pass below is the backstop for what it still misses.
        if (total > 0 && armW / total >= 0.8) isArm[v] = 1;
    }

    const index = geo.index;
    const triCount = index ? index.count / 3 : pos.count / 3;
    const keep = [];
    for (let t = 0; t < triCount; t++) {
        const a = index ? index.getX(t * 3) : t * 3;
        const b = index ? index.getX(t * 3 + 1) : t * 3 + 1;
        const c = index ? index.getX(t * 3 + 2) : t * 3 + 2;
        // All three, not any: a triangle straddling the shoulder seam would
        // otherwise stretch from the hand into the chest.
        if (isArm[a] && isArm[b] && isArm[c]) keep.push(a, b, c);
    }
    if (keep.length < 60) return null;    // nothing recognisable was found

    // Reject islands that are NOT ON THE ARM, by distance from the arm's own
    // bone chain.
    //
    // The first attempt kept the largest connected component, on the theory
    // that an arm is one piece. It is not: armour plates, a sleeve and a hand
    // are separate shells, so "largest component" kept a single pauldron and
    // threw the rest away - 5,150 triangles became 558. Measuring against the
    // BONES instead keeps every shell that sits on the arm and rejects the
    // stray patch of hip that the weight threshold let through.
    const chain = [];
    for (const part of ARM_CHAIN) {
        for (const b of skinned.skeleton.bones) {
            const n = b.name || '';
            if (n.indexOf(part) !== 0) continue;
            if (n.slice(part.length).replace(/[._]/g, '') !== side) continue;
            b.updateWorldMatrix(true, false);
            chain.push(new THREE.Vector3().setFromMatrixPosition(b.matrixWorld));
            break;
        }
    }
    if (chain.length >= 2) {
        // Bone positions are in WORLD space; vertices are in the mesh's local
        // space. Bring the chain into the mesh's space rather than the other
        // way round - there are three bones and thousands of vertices.
        skinned.updateWorldMatrix(true, false);
        const toLocal = new THREE.Matrix4().copy(skinned.matrixWorld).invert();
        const local = chain.map(v => v.clone().applyMatrix4(toLocal));
        let chainLen = 0;
        for (let i = 1; i < local.length; i++) chainLen += local[i].distanceTo(local[i - 1]);
        // Deliberately loose: an arm's shells stand off the bone by a real
        // amount, and a false reject is a HOLE in the model. Tightening this
        // to 0.22 to chase the detached fragment cost Lyra two thirds of her
        // sleeve and changed Draven by two triangles - which is what proved
        // distance was never what made the fragment detach. See ARM_CHAIN.
        const maxDist = Math.max(1e-4, chainLen * 0.45);
        const _c = new THREE.Vector3(), _ab = new THREE.Vector3(), _ap = new THREE.Vector3();
        const nearChain = (x, y, z) => {
            _c.set(x, y, z);
            let best = Infinity;
            for (let i = 1; i < local.length; i++) {
                const a = local[i - 1], b2 = local[i];
                _ab.subVectors(b2, a);
                const denom = _ab.dot(_ab);
                const t = denom <= 1e-12 ? 0 : Math.max(0, Math.min(1, _ap.subVectors(_c, a).dot(_ab) / denom));
                const d = _c.distanceTo(_ap.copy(a).addScaledVector(_ab, t));
                if (d < best) best = d;
            }
            return best <= maxDist;
        };
        // ...and clip anything INBOARD OF THE SHOULDER.
        //
        // Two problems, one cut. The weight threshold and the proximity test
        // together still left a small shard of torso hanging off the shoulder
        // (it is genuinely close to the shoulder bone, so no distance test can
        // reject it), and the deltoid end was a ragged hole where the triangles
        // were sliced. Projecting onto the shoulder-to-hand axis and dropping
        // everything behind the shoulder removes both - and costs nothing
        // visually, because in first person the shoulder is behind the camera.
        const axisA = local[0], axisB = local[local.length - 1];
        const axis = new THREE.Vector3().subVectors(axisB, axisA);
        const axisLen2 = Math.max(1e-9, axis.dot(axis));
        const _pv = new THREE.Vector3();
        const alongArm = (x, y, z) => _pv.set(x, y, z).sub(axisA).dot(axis) / axisLen2;

        const filtered = [];
        for (let i = 0; i < keep.length; i += 3) {
            const a = keep[i], b2 = keep[i + 1], c = keep[i + 2];
            const cx = (pos.getX(a) + pos.getX(b2) + pos.getX(c)) / 3;
            const cy = (pos.getY(a) + pos.getY(b2) + pos.getY(c)) / 3;
            const cz = (pos.getZ(a) + pos.getZ(b2) + pos.getZ(c)) / 3;
            if (!nearChain(cx, cy, cz)) continue;
            if (alongArm(cx, cy, cz) < 0.06) continue;   // behind the shoulder
            filtered.push(a, b2, c);
        }
        if (filtered.length >= 60) { keep.length = 0; keep.push(...filtered); }

        // NOTE ON WHAT IS **NOT** DONE HERE.
        //
        // Two component filters used to live at this point, both operating on
        // BIND-POSE positions, and both were no-ops. Measuring the result is
        // what explained it: the leftover fragment on Draven is a 256-triangle
        // piece of his tasset that auto-weighting bound to the arm bones, and
        // in the BIND pose - a T-pose, arm horizontal at shoulder height - it
        // sits right beside the upper arm. There is nothing to distinguish it
        // from real arm geometry until the arm is POSED, at which point the arm
        // swings forward and the tasset stays behind.
        //
        // So the detached-piece prune happens after baking instead, on the
        // posed geometry, where the separation is real and obvious. See
        // _prunePosedComponents.
    }

    return keep;
}

// Builds a viewmodel arm from the character's loaded model, or returns null.
// Poses the arm chain into a first-person carry, then BAKES THE SKINNED RESULT.
//
// The first version baked the BIND pose - a T-pose, arm straight out to the
// side - and then rigidly rotated the whole slab of geometry to point it into
// the screen. That is why the arms came out "backwards and sometimes separated
// and weird": a rigid rotation carries the hand's orientation with it, so the
// palm ended up facing outward, and the shoulder end was sheared across the
// direction the deltoid was actually modelled in.
//
// Posing the skeleton first and reading the SKINNED vertex positions is the
// difference between "the arm mesh, turned" and "the arm, held". The bone axes
// are not guessed: art/pipeline.py built these rigs and documents them -
//     swing  -> local X, NEGATIVE IS FORWARD, same sign on both sides
//     spread -> local Z, mirrored on .R
//     twist  -> local Y, mirrored on .R
// so a first-person carry is a big negative X on the upper arm (swing it
// forward), a bend at the elbow, and a little spread to bring it inboard.
// WHERE THE LIMB SHOULD POINT, not how far to rotate each joint.
//
// The first attempt set euler angles on the bones, using art/pipeline.py's
// documented convention ("swing -> local X, negative = forward"). That
// convention is real, but it describes the rig's own REST pose, and these
// characters are bound in a T-POSE: for an arm already pointing straight out
// to the side, the bone's local X runs along the arm, so rotating about it
// swings the limb up and down rather than forward. The result was an arm
// hanging straight down.
//
// Directions do not have this problem. Each vector below is in the character's
// own space - it faces local +X, which is what render3D relies on - and
// _aimBone works out the rotation that gets there. No axis convention to be
// wrong about, and it behaves identically on a rig bound in an A-pose.
//
// The shape being described is an ordinary first-person carry: upper arm
// hanging down and a little forward, forearm swung forward into view with the
// elbow bent, both tucked slightly inboard so the hand sits near the middle of
// the frame rather than at the edge.
function _aimBone(bone, child, targetWorldDir) {
    if (!bone || !child) return;
    bone.updateWorldMatrix(true, false);
    child.updateWorldMatrix(true, false);
    const a = new THREE.Vector3().setFromMatrixPosition(bone.matrixWorld);
    const b = new THREE.Vector3().setFromMatrixPosition(child.matrixWorld);
    const from = b.clone().sub(a);
    if (from.lengthSq() < 1e-10) return;
    from.normalize();
    const to = targetWorldDir.clone().normalize();
    const q = new THREE.Quaternion().setFromUnitVectors(from, to);

    const boneWorldQ = new THREE.Quaternion();
    bone.matrixWorld.decompose(new THREE.Vector3(), boneWorldQ, new THREE.Vector3());
    const want = q.multiply(boneWorldQ);          // the world rotation we want

    const parentWorldQ = new THREE.Quaternion();
    if (bone.parent) {
        bone.parent.updateWorldMatrix(true, false);
        bone.parent.matrixWorld.decompose(new THREE.Vector3(), parentWorldQ, new THREE.Vector3());
    }
    bone.quaternion.copy(parentWorldQ.invert().multiply(want));
    bone.updateMatrixWorld(true);
}

// Bakes the CURRENT pose of a skinned mesh into a plain BufferGeometry,
// keeping only the triangles listed in `keep`.
//
// SkinnedMesh.boneTransform(i, v) does the CPU skinning for one vertex - the
// same weighted-matrix sum the vertex shader does - which is exactly what is
// needed to freeze a pose. Normals are recomputed afterwards rather than
// transformed: three offers no normal equivalent, and for a smooth-shaded limb
// recomputing is both simpler and correct.
// Drops connected pieces of a POSED arm that are not on the arm any more.
//
// This is the filter that actually removed the reported "sometimes look
// separated and weird", and it has to run here rather than during triangle
// selection - see the note in _armTriangles. `chainPts` are the posed bone
// positions in the same space as the geometry; `radius` is about an arm radius.
//
// Vertices are welded by position first: a UV seam duplicates vertices at
// identical coordinates, and without welding one continuous shell splits into
// several that each look detached, which would make this filter delete the arm.
function _sealArmCut(mesh) {
    const mats = Array.isArray(mesh.material) ? mesh.material : [mesh.material];
    const inner = mats[0].clone();
    inner.side = THREE.BackSide;
    // Slightly darkened: it is the inside of a limb, not a lit exterior, and at
    // full brightness the interior reads as a second surface rather than depth.
    if (inner.color) inner.color.multiplyScalar(0.55);
    inner.userData.keepMap = true;     // shares the source model's textures
    const shell = new THREE.Mesh(mesh.geometry, inner);
    shell.userData.noOutline = true;   // see addRimOutline
    shell.renderOrder = (mesh.renderOrder || 0) - 1;
    mesh.add(shell);
    return shell;
}

// Maps a weapon's attack type to a first-person viewmodel motion, so a sword
// slashes across the view, a dagger jabs, a hammer comes down overhead, fists
// piston in and out, and casters recoil — instead of one generic lunge.
function syncViewmodels(dt) {
    const pairs = [[vmP1, player1], [vmP2, player2]];
    for (const [vm, f] of pairs) {
        if (!vm || !f) continue;
        const bob = Math.sin(arenaTime * 0.08) * 0.35;
        const bx = vm.userData.baseX, by = vm.userData.baseY, bz = vm.userData.baseZ;
        const acting = f.atkState !== 'idle' && f.atkKind;
        const fd = acting ? FRAME_DATA[f.name][f.atkKind] : null;
        const kind = vm.userData.animKind;
        let px = bx, py = by + bob, pz = bz, rx = 0, ry = 0, rz = 0;
        if (acting && fd) {
            const su = Math.max(1, fd.startup), av = Math.max(1, fd.active), rc = Math.max(1, fd.recovery);
            if (f.atkKind === 'special') {
                // Each special has its own elaborate first-person motion.
                let wind = 0, strike = 0, pg = 1;
                if (f.atkState === 'startup') wind = 1 - f.atkStateTimer / su;
                else if (f.atkState === 'active') { wind = 1; strike = 1 - f.atkStateTimer / av; }
                else { wind = 1; strike = 1; pg = f.atkStateTimer / rc; }
                const sp = vm.userData.special;
                if (sp === 'dash') { pz = bz + wind * 3 - strike * 14 * pg; rx = -0.15 * pg; px = bx - strike * 1.5 * pg; } // explosive forward thrust
                else if (sp === 'groundbreak' || sp === 'shockwave') { const raise = wind * (1 - strike); rx = (-1.2 * raise + 2.0 * strike) * pg; py = by + bob + (raise * 6 - strike * strike * 11) * pg; pz = bz - strike * 4 * pg; } // overhead slam
                else if (sp === 'flurry') { const p = f.atkState === 'active' ? strike : 0; const reach = 0.5 - 0.5 * Math.cos(p * Math.PI * 2 * 5); pz = bz - reach * 8 - (f.atkState === 'active' ? Math.max(0, 1 - strike * 3) * 4 : 0); px = bx + Math.sin(reach * Math.PI) * 2; } // blink-in stab storm
                else if (sp === 'ward') { const r = (f.atkState === 'recovery') ? pg : (f.atkState === 'startup' ? wind : 1); rx = -r * 0.6; py = by + bob + r * 3.5; pz = bz + r; } // raise a glowing guard, hold
                else if (sp === 'thunder') { if (f.atkState === 'active') { rx = -1.0 + strike * 1.6; py = by + bob + 4 - strike * 7; pz = bz - strike * 2; } else { rx = -1.0 * wind; py = by + bob + 4 * wind; pz = bz + wind; } } // point to sky, snap down
                else if (sp === 'volley') { const r = (f.atkState === 'recovery') ? pg : (f.atkState === 'startup' ? wind : 1); rx = -r * 0.4; ry = (f.atkState === 'active') ? (-0.35 + 0.7 * strike) : 0; py = by + bob + r * 1.5; pz = bz + (f.atkState === 'active' ? Math.abs(Math.sin(strike * Math.PI * 5)) * 1.5 : r); } // sweep the fan
                else if (sp === 'inferno') { if (f.atkState === 'startup') { pz = bz + wind * 3; py = by + bob - wind * 2; } else { pz = bz - strike * 9 * pg; py = by + bob + strike * 3 * pg; rx = -0.1; } } // draw in, then burst forward
                else { const t = swingT(f, fd), u = (1 - t) / 2; rz = _vmLerp(1.0, -1.7, u); ry = _vmLerp(-0.55, 0.95, u); rx = _vmLerp(-0.5, 0.5, u); px = bx + _vmLerp(3.5, -4.5, u); py = by + bob + _vmLerp(2, -2.5, u); pz = bz - (f.atkState === 'active' ? 4 : 0); } // reap / bramble — big wide sweep
            } else if (kind === 'swing') {
                // Diagonal slash: wind up upper-right, sweep down-left across view.
                const t = swingT(f, fd), u = (1 - t) / 2; // 0 = wind-up extreme, 1 = follow-through
                rz = _vmLerp(0.7, -1.35, u); ry = _vmLerp(-0.4, 0.75, u); rx = _vmLerp(-0.45, 0.4, u);
                px = bx + _vmLerp(2.5, -3.8, u); py = by + bob + _vmLerp(1.6, -2, u);
                pz = bz - (f.atkState === 'active' ? 3.5 : 0);
            } else if (kind === 'stab') {
                let reach = 0;
                if (f.atkState === 'active') { const p = 1 - f.atkStateTimer / av; reach = Math.max(0, Math.sin(p * Math.PI * 2)); } // two quick thrusts
                else if (f.atkState === 'startup') reach = -0.25 * (1 - f.atkStateTimer / su); // cock back
                else reach = 0.12 * (f.atkStateTimer / rc);
                pz = bz - reach * 9; px = bx + reach * 1.4; rx = -0.1 - reach * 0.15;
            } else if (kind === 'overhead') {
                if (f.atkState === 'startup') { const r = 1 - f.atkStateTimer / su; rx = -r * 1.05; py = by + bob + r * 5.5; pz = bz + r * 1.5; }
                else if (f.atkState === 'active') { const p = 1 - f.atkStateTimer / av; rx = -1.05 + p * 1.8; py = by + bob + 5.5 - p * 10; pz = bz - p * 4; }
                else { const r = f.atkStateTimer / rc; rx = 0.55 * r; py = by + bob - 2.5 * r; }
            } else if (kind === 'jab') {
                let reach = 0;
                if (f.atkState === 'active') { const p = 1 - f.atkStateTimer / av; reach = 0.5 - 0.5 * Math.cos(p * Math.PI * 4); } // two piston jabs
                pz = bz - reach * 7; px = bx + Math.sin(reach * Math.PI) * 1.4; rx = -0.06;
            } else if (kind === 'cast') {
                // Recoil kick: weapon snaps back + muzzle-up as the shot leaves.
                if (f.atkState === 'startup') { const r = 1 - f.atkStateTimer / su; pz = bz + r * 2; rx = -r * 0.3; py = by + bob + r; }
                else if (f.atkState === 'active') { const k = f.atkStateTimer / av; pz = bz + k * 3.5; rx = -k * 0.4; py = by + bob + k * 1.8; }
                else { const r = f.atkStateTimer / rc; pz = bz + r; }
            }
        }
        vm.position.set(px, py, pz);
        // The arm's resting roll is part of the BASE, not a one-time setting.
        // syncViewmodels ASSIGNS rotation every frame, so a roll applied at
        // build time survives exactly until the first frame - which is how a
        // carefully-tipped viewmodel ends up flat again in play and fine in
        // every screenshot taken before the loop runs.
        vm.rotation.set(rx, ry, rz + (vm.userData.baseRoll || 0));
        const flash = vm.userData.flash;
        if (flash) {
            const t = Math.max(0, (f.muzzleFlash || 0) / 7);
            flash.visible = t > 0;
            flash.material.opacity = t;
            flash.scale.setScalar(0.8 + (1 - t) * 1.8);
            if (t > 0) flash.material.color.set(hexNum(f.color));
        }
        // Magical charge glow for casters: swells through the wind-up.
        const charge = vm.userData.charge;
        if (charge) {
            let c = 0;
            if (acting && fd) {
                if (f.atkState === 'startup') c = 1 - f.atkStateTimer / Math.max(1, fd.startup);
                else if (f.atkState === 'active') c = 1;
                else c = (f.atkStateTimer / Math.max(1, fd.recovery)) * 0.4;
            }
            charge.visible = c > 0.03;
            charge.material.opacity = 0.55 * c + (f.atkState === 'active' ? 0.3 * Math.abs(Math.sin(arenaTime * 0.5)) : 0);
            charge.scale.setScalar(0.5 + c * 2.3);
        }
    }
}

// THE PROCEDURAL CHARACTER BODIES live in shared/characters.js, loaded
// above: one copy, shared with the local build.
const charModels = {};

function animateWeapon(f) {
    const acting = f.atkState !== 'idle' && f.atkKind;
    const anim = (acting && f.atkKind === 'special' && f.mesh.userData.specialAnim) ? f.mesh.userData.specialAnim : f.mesh.userData.weaponAnim;
    const arms = armsOf(f);
    const weapon = f.mesh.userData.weapon;
    const ws = (weapon && weapon.scale) ? weapon : null; // dual-wielders store an array here — only a single mesh is scalable
    if (ws) ws.scale.setScalar(1); // reset transient weapon scale each frame (additive body offsets are reset by render3D)
    const chargeOrb = f.mesh.userData.chargeOrb || null; // set by the caster mesh builders
    if (chargeOrb) chargeOrb.visible = false;
    if (!anim) return;
    const fd = acting ? FRAME_DATA[f.name][f.atkKind] : null;

    // Per-phase amounts: wind (0->1 through startup, held), strike (0->1 across
    // active), and poseGain that eases the whole pose back to rest in recovery.
    let wind = 0, strike = 0, poseGain = 1;
    if (acting && fd) {
        const su = Math.max(1, fd.startup), av = Math.max(1, fd.active), rc = Math.max(1, fd.recovery);
        if (f.atkState === 'startup') wind = 1 - f.atkStateTimer / su;
        else if (f.atkState === 'active') { wind = 1; strike = 1 - f.atkStateTimer / av; }
        else { wind = 1; strike = 1; poseGain = f.atkStateTimer / rc; }
    }

    // ---- Basic attack motions ----
    if (anim.type === 'swing') {
        const t = acting ? swingT(f, fd) : 0;
        // The WIND-UP IS CAPPED AGAINST THE STRIKE, because an attack that
        // travels further backward than forward reads as a swing behind the
        // fighter however correct its axis is. Nyx is the case that found it:
        // -60 back against a 105 forward that the shoulder clamp cuts to 95,
        // and her arm rests further forward than anyone else's (a scythe
        // carry), so she measured 20 units back against 10 forward.
        //
        // Capped rather than re-authored per character: the rule is what
        // matters, and it holds for whatever the data says next.
        const fwd = Math.min(SWING_MAX_FWD, anim.fwdDeg);
        const back = Math.max(anim.backDeg, -SWING_BACK_FRAC * fwd);
        const deg = t >= 0 ? t * back : -t * fwd;
        _applyArms(arms, deg, f);
        if (anim.twistDeg) f.mesh.rotation.y += t * anim.twistDeg * DEG;
    } else if (anim.type === 'stab') {
        let reach = 0;
        if (acting) {
            if (f.atkState === 'active') { const p = 1 - f.atkStateTimer / Math.max(1, fd.active); reach = 0.5 - 0.5 * Math.cos(p * Math.PI * 2 * readableJabs(anim.jabs, fd.active)); }
            else if (f.atkState === 'startup') reach = -0.3 * wind;
            else reach = 0.15 * poseGain;
        }
        _applyArms(arms, reach * anim.reachDeg, f);
    } else if (anim.type === 'flurry') {
        // A FLURRY THAT IS ACTUALLY DRAWN, which the old one was not.
        //
        // "ignis's attack is a snap that doesn't have a smooth animation": his
        // active window is SIX FRAMES, and the old envelope spent half of each
        // cycle clamped at zero (max(0, sin) parks an arm for its negative
        // half) and reset to rest the instant the window ended. Net effect at
        // 60fps: the arm appeared forward for two frames and was at rest for
        // every other frame of the attack.
        //
        // Now the motion spans the WHOLE action - it leans in through startup,
        // alternates arms with a half-sine each (no dead half, so every frame
        // draws a different position), and eases back out through recovery.
        // Same jab count, same timing data; it is just continuous.
        // fd is null whenever the fighter is NOT mid-attack, and this branch
        // runs every frame - reading fd.active unguarded threw on the very
        // first idle frame and took the whole animation path down with it,
        // which then made every later measurement in swingcheck a stale value.
        const jabs = readableJabs(anim.jabs, fd ? fd.active : 1);
        const halves = Math.max(1, jabs * arms.length);
        let env = i => 0;
        if (acting && f.atkState === 'active') {
            const p = 1 - f.atkStateTimer / Math.max(1, fd.active);
            const cyc = p * halves;                    // half-cycles elapsed
            const owner = Math.floor(cyc) % Math.max(1, arms.length);
            const frac = cyc - Math.floor(cyc);
            env = i => (i === owner ? Math.sin(Math.PI * frac) : 0.12);
        } else if (acting && f.atkState === 'startup') {
            env = () => -0.22 * wind;                  // a small draw back
        } else if (acting) {
            env = () => 0.3 * poseGain;                // settle out of the last jab
        }
        _reachArms(arms, i => env(i) * anim.reachDeg, f);
    } else if (anim.type === 'cast') {
        let raise = 0;
        if (acting) { if (f.atkState === 'startup') raise = wind; else if (f.atkState === 'active') raise = 1; else raise = poseGain; }
        _applyArms(arms, raise * (anim.raiseDeg || 90), f);
        if (ws) ws.scale.setScalar(1 + raise * ((anim.peakScale || 1.6) - 1));
        _castCharge(chargeOrb, f, wind, strike, poseGain);
    // ---- Special motions ----
    } else if (anim.type === 'dash') {
        _applyArms(arms, (-40 * wind + 120 * strike) * poseGain, f); // draw back, then drive the blade forward
        const lunge = strike * strike * 26 * poseGain;
        f.mesh.position.x += f.fx * lunge; f.mesh.position.z += f.fy * lunge;
        f.mesh.position.y += Math.sin(strike * Math.PI) * 2 * poseGain;
    } else if (anim.type === 'slam') {
        const big = anim.big ? 1.25 : 1;
        _applyArms(arms, (-95 * wind + 150 * strike) * big * poseGain, f); // hoist overhead, crash down
        f.mesh.position.y += (wind * 5 - strike * strike * 9 * big) * poseGain;
        if (ws) ws.scale.setScalar(1 + (0.25 * wind + 0.45 * strike) * big);
    } else if (anim.type === 'reap') {
        _applyArms(arms, (-60 * wind + 70 * strike) * poseGain, f);
        f.mesh.rotation.y += -Math.PI * 2 * strike * poseGain; // full spinning reap
        f.mesh.position.y += Math.sin(strike * Math.PI) * 5 * poseGain;
        if (ws) ws.scale.setScalar(1 + 0.2 * Math.sin(strike * Math.PI));
    } else if (anim.type === 'blinkflurry') {
        const jabs = anim.jabs || 5, reachDeg = anim.reachDeg || 105;
        const on = f.atkState === 'active';
        const phase = on ? strike * Math.PI * 2 * jabs : 0;
        _reachArms(arms, i => {
            const sv = on ? Math.max(0, Math.sin(phase + i * Math.PI))
                          : (f.atkState === 'startup' ? -0.3 * wind : 0);
            return sv * reachDeg * (on ? 1 : poseGain);
        }, f);
        if (on) { const blink = Math.max(0, 1 - strike * 3); f.mesh.position.x += f.fx * 10 * blink; f.mesh.position.z += f.fy * 10 * blink; } // quick blink-in
    } else if (anim.type === 'skybolt') {
        const armDeg = (f.atkState === 'active') ? (-150 + 230 * strike) : -150 * wind; // point to sky, then snap down-forward
        _applyArms(arms, armDeg * poseGain, f);
        f.mesh.position.y += wind * 2 * poseGain;
        if (ws) ws.scale.setScalar(1 + wind * 0.7 + Math.sin(strike * Math.PI) * 1.1);
        _castCharge(chargeOrb, f, wind, strike, poseGain);
    } else if (anim.type === 'flameburst') {
        if (f.atkState === 'startup') { _applyArms(arms, -50 * wind, f); f.mesh.position.y -= 4 * wind; }
        else { _applyArms(arms, (-50 + 160 * strike) * poseGain, f); f.mesh.position.y += (-4 + strike * 7) * poseGain; }
        if (ws) ws.scale.setScalar(1 + strike * 0.7);
    } else if (anim.type === 'volley') {
        const raise = (f.atkState === 'recovery') ? poseGain : (f.atkState === 'startup' ? wind : 1);
        _applyArms(arms, raise * 95, f);
        if (f.atkState === 'active') f.mesh.rotation.y += (-0.35 + 0.7 * strike) * poseGain; // sweep the fan across
        if (ws) ws.scale.setScalar(1 + 0.5 * Math.abs(Math.sin(strike * Math.PI * 5)) + raise * 0.3);
        _castCharge(chargeOrb, f, wind, strike, poseGain);
    } else if (anim.type === 'ward') {
        const raise = (f.atkState === 'recovery') ? poseGain : (f.atkState === 'startup' ? wind : 1);
        _applyArms(arms, raise * 82, f);
        if (ws) { ws.scale.setScalar(1 + raise * 0.9); ws.rotation.y += 0.06 * raise; }
        f.mesh.position.y += Math.sin(arenaTime * 0.12) * 0.6 * raise;
        _castCharge(chargeOrb, f, wind, strike, poseGain);
    } else if (anim.type === 'whipsweep') {
        const t = acting ? swingT(f, fd) : 0;
        const deg = t >= 0 ? t * -70 : -t * 130;
        _applyArms(arms, deg, f);
        f.mesh.rotation.y += t * 80 * DEG; // big body twist for the wide lash
        f.mesh.position.y += Math.abs(t) * 2;
    }
}

// Magical charge glow at a caster's weapon core: swells + brightens through
// the wind-up, flickers bright on release, fades out through recovery.
function createEffectMesh(e, originX, originY) {
    if (e.type === 'streak') {
        const dx = e.x2 - e.x1, dy = e.y2 - e.y1;
        const mesh = new THREE.Mesh(
            new THREE.BoxGeometry(Math.max(1, Math.hypot(dx, dy)), 3, 6),
            new THREE.MeshBasicMaterial({ color: new THREE.Color(`rgb(${e.color})`), transparent: true, opacity: 1 })
        );
        mesh.position.set(worldX((e.x1 + e.x2) / 2), 8, worldZ((e.y1 + e.y2) / 2));
        mesh.rotation.y = -Math.atan2(dy, dx);
        scene.add(mesh);
        return mesh;
    }

    if (e.type === 'shockwaveRing') {
        const mesh = new THREE.Mesh(
            getCachedGeometry('shockwaveRing', () => new THREE.RingGeometry(0.82, 1, 40)),
            new THREE.MeshBasicMaterial({ color: new THREE.Color(`rgb(${e.color})`), transparent: true, opacity: 0.8, side: THREE.DoubleSide })
        );
        mesh.rotation.x = -Math.PI / 2;
        mesh.position.set(worldX(originX), 2, worldZ(originY));
        scene.add(mesh);
        return mesh;
    }

    // Slash/dagger are attacker-centered sweeping cones — render the real
    // arc (matching the hit cone's halfAngle) instead of a full ring, and
    // orient it via rotateOnWorldAxis so composing the flattening rotation
    // with the facing yaw can't land in an ambiguous combined-Euler state.
    if (e.type === 'slash' || e.type === 'dagger' || e.type === 'scythe' || e.type === 'whip') {
        const isDagger = e.type === 'dagger';
        const radius = (e.range || (isDagger ? 55 : 65)) * (isDagger ? 0.55 : 0.75);
        const bandInner = isDagger ? radius - 3 : radius - 8;
        const segs = isDagger ? 16 : 24;
        const geoKey = `arc:${bandInner.toFixed(2)}:${radius.toFixed(2)}:${segs}:${e.halfAngle.toFixed(4)}`;
        const mesh = new THREE.Mesh(
            getCachedGeometry(geoKey, () => new THREE.RingGeometry(Math.max(1, bandInner), radius, segs, 1, -e.halfAngle, e.halfAngle * 2)),
            new THREE.MeshBasicMaterial({ color: new THREE.Color(`rgb(${effectColor(e)})`), transparent: true, opacity: 0.85, side: THREE.DoubleSide })
        );
        mesh.rotation.x = -Math.PI / 2;
        mesh.position.set(worldX(originX), 6, worldZ(originY));
        mesh.rotateOnWorldAxis(new THREE.Vector3(0, 1, 0), e.angle);
        scene.add(mesh);
        return mesh;
    }

    // Punch/hammer are offset impact bursts, not swept cones — a chunky
    // low-segment ring (near-polygonal) reads as a burst rather than a
    // smooth circle, and is cheap to tell apart from slash/dagger at a glance.
    let px = originX, py = originY, radius, segments;
    if (e.type === 'punch') { px += Math.cos(e.angle) * (e.range || 60) * 0.6; py += Math.sin(e.angle) * (e.range || 60) * 0.6; radius = 18; segments = 8; }
    else if (e.type === 'hammer') { px += Math.cos(e.angle) * (e.range || 75) * 0.6; py += Math.sin(e.angle) * (e.range || 75) * 0.6; radius = 27; segments = 10; }
    else { radius = 24; segments = 28; } // ward

    const mesh = new THREE.Mesh(
        getCachedGeometry(`burst:${e.type}:${radius}:${segments}`, () => new THREE.RingGeometry(Math.max(1, radius - 5), radius, segments)),
        new THREE.MeshBasicMaterial({ color: new THREE.Color(`rgb(${effectColor(e)})`), transparent: true, opacity: 0.8, side: THREE.DoubleSide })
    );
    mesh.rotation.x = -Math.PI / 2;
    mesh.position.set(worldX(px), 2, worldZ(py));
    scene.add(mesh);
    return mesh;
}

// --- Menu setup: both players pick independently and simultaneously.
// Picking a fighter doesn't lock it in — it opens a description panel
// (stats + abilities) filling that player's half of the screen. Attack
// confirms, Special backs out to the roster. The fight starts the moment
// both sides have confirmed. ---

let botDifficulty = 'normal';

function specialDamageText(c) {
    if (c.specialKind === 'shield') return 'Shield';
    const hits = c.specialHits || 1;
    let t = String(specialDamageValue(c));
    if (hits > 1) t += ` (${c.specialDmg}×${hits})`;
    if (c.specialDot) t += ' incl. burn';
    return t;
}

// --- Batch 19: game-mode select. A modal following the mapselect precedent
// (opened mid-flow, closes back to whatever was underneath) rather than a new
// top-level screen. Deliberately NOT a gate in front of fighter-select:
// 'classic' is already a valid choice, so nothing needs to be blocked until a
// mode is explicitly chosen — same flag-don't-block stance as the existing
// mirror-match handling. ---
// Every mode is available online now, co-op included.
//
// Batch 34 excluded the co-op modes with a real reason: their enemies are
// AI-driven, AI was not part of the netcode, and two clients each running their
// own boss from their own frame timing diverge on the first hit. The reason was
// sound; the conclusion - leave them out - was only correct while nothing
// owned the enemies.
//
// Batch 42 gives them an owner. The HOST simulates every co-op enemy and
// broadcasts their state; the guest never runs enemy AI at all and draws them
// from the wire, exactly as it already does for the opponent fighter. That is
// the same authority model the rest of the netcode uses, applied to a third
// party instead of a second one - see netCoopState / coopIsPuppet.
function onlineModes() { return MATCH_MODES.slice(); }

let matchStats = null;

function freshStats() {
    return { damageDealt: 0, largestHit: 0, specialsUsed: 0 };
}

// Visual half of Arena Collapse: shrink the floor plane to the current play
// bounds and drop any map geometry now outside them into the void, so the
// arena visibly disappears from the edges inward. Replaces the old red wall
// slabs (which obscured the fight); nothing is drawn "at" the boundary now —
// the boundary is simply where the floor and props stop existing.
function syncArenaCollapse(dt) {
    dt = dt || 1;
    if (!floorMesh) return;
    const xExt = Math.max(1, playRight - playLeft);
    const zExt = Math.max(1, playBottom - playTop);
    floorMesh.scale.x = xExt / floorBaseSize.w;
    floorMesh.scale.y = zExt / floorBaseSize.d; // plane's local Y maps to world Z after the -90° flip
    floorMesh.position.set(worldX((playLeft + playRight) / 2), 0, worldZ((playTop + playBottom) / 2));
    syncOuterWalls(); // the four enclosing walls physically slide inward with the bounds

    // Each pillar/terrain/platform: once its game-space position is outside
    // the shrinking bounds, it starts falling (drops straight down through
    // where the floor used to be) and is hidden once well below — a clean
    // per-instance transform, no shared-material opacity to worry about.
    for (const o of mapEdgeObjects) {
        if (!o.falling && (o.x < playLeft || o.x > playRight || o.y < playTop || o.y > playBottom)) {
            o.falling = true;
        }
        if (o.falling && o.mesh.visible) {
            o.mesh.position.y -= 3.5 * dt;
            if (o.mesh.position.y < -180) o.mesh.visible = false;
        }
    }
}

// Pushbox: keeps the two fighters from ever standing exactly on top of
// each other. Circle-to-circle against their footprint radius; ignored
// if one is well above the other in height (mid-jump over/past them).
function resolvePlayerCollision(a, b) {
    if (Math.abs(a.z - b.z) > 40) return;
    const ax = a.x + a.width / 2, ay = a.y + a.height / 2;
    const bx = b.x + b.width / 2, by = b.y + b.height / 2;
    const dx = bx - ax, dy = by - ay;
    const dist = Math.hypot(dx, dy) || 1;
    const minDist = a.width / 2 + b.width / 2 - 8; // small overlap allowance so melee doesn't feel like a wall
    if (dist < minDist) {
        const push = (minDist - dist) / 2;
        const nx = dx / dist, ny = dy / dist;
        a.x -= nx * push; a.y -= ny * push;
        b.x += nx * push; b.y += ny * push;
        a.clampToArena(); b.clampToArena();
    }
}

// --- Intro drop-in cinematic: at match start both fighters plummet from the
// sky into the arena, frozen, then a "FIGHT!" flash unlocks control. In first
// person each player's own view falls with them, right into the arena. ---
let introTimer = 0, introPhase = 'drop';

// Who is allowed to run a fighter's respawn clock. The same rule as every
// other piece of fighter state: each client owns its own, so two machines can
// never disagree about whether you are back yet. The countdown the other side
// SEES arrives on the wire (STATE.dn) and is display-only.
function coopOwnsRespawn(f) { return !netActive() || isLocalSide(sideOf(f)); }

// ?debug=1: hitboxes/hurtboxes, facing vectors, dt, FPS, and each
// fighter's action state machine, drawn on the HUD canvas.
function computeDt() {
    const now = performance.now();
    let dt = (now - lastFrameTime) / (1000 / 60);
    lastFrameTime = now;
    return Math.min(dt, 3); // clamp so a tab-switch/lag spike can't jump physics far
}

// Is the keyboard currently talking to a text field rather than to the game?
//
// Checked at the ONE place every keystroke passes through, rather than in each
// hotkey handler: there are a dozen of those and the thirteenth would forget.
// isContentEditable covers rich-text hosts; the tag check covers everything
// else, including <input type="range"> sliders, where arrow keys belong to the
// control and not to the fighter.
function typingInField(target) {
    const el = target || document.activeElement;
    if (!el) return false;
    if (el.isContentEditable) return true;
    const tag = el.tagName;
    return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
}

// Offset ashlar-style block courses shared by stone/sandstone/marble/redrock.
function _redStrata(g, bx, by, bw, bh) { g.fillStyle = 'rgba(80,40,25,0.16)'; for (let yy = by + 4; yy < by + bh; yy += 6) g.fillRect(bx, yy, bw, 2); }

function getWallTexture(theme) {
    if (wallTextureCache[theme.id]) return wallTextureCache[theme.id];
    const g = _canvas();
    const acc = hexToCss(theme.accent, 0.85);
    if (theme.wallTex === 'metal') {
        g.fillStyle = '#28374f'; g.fillRect(0, 0, 256, 256);
        for (let y = 0; y < 256; y += 64) for (let x = 0; x < 256; x += 64) {
            const gr = g.createLinearGradient(x, y, x, y + 64); gr.addColorStop(0, '#38507a'); gr.addColorStop(1, '#243349');
            g.fillStyle = gr; g.fillRect(x + 3, y + 3, 58, 58);
            g.strokeStyle = 'rgba(0,0,0,0.45)'; g.lineWidth = 2; g.strokeRect(x + 3, y + 3, 58, 58);
        }
        g.fillStyle = acc; g.fillRect(0, 125, 256, 4); g.fillRect(125, 0, 4, 256); // glowing seams
        g.fillStyle = 'rgba(200,225,255,0.3)';
        for (let y = 0; y <= 256; y += 64) for (let x = 0; x <= 256; x += 64) { g.beginPath(); g.arc(x, y, 2.5, 0, 6.283); g.fill(); }
    } else if (theme.wallTex === 'ice') {
        const gr = g.createLinearGradient(0, 0, 0, 256); gr.addColorStop(0, '#dceffa'); gr.addColorStop(1, '#a9d6ea');
        g.fillStyle = gr; g.fillRect(0, 0, 256, 256);
        g.strokeStyle = 'rgba(255,255,255,0.4)'; g.lineWidth = 1;
        for (let i = 0; i < 20; i++) { const x = Math.random() * 256, y = Math.random() * 256; g.beginPath(); g.moveTo(x, y); g.lineTo(x + Math.random() * 60 - 30, y + Math.random() * 60 - 30); g.stroke(); }
        g.strokeStyle = 'rgba(90,140,180,0.35)'; g.lineWidth = 1.5;
        for (let i = 0; i < 8; i++) { let x = Math.random() * 256, y = 0; g.beginPath(); g.moveTo(x, y); for (let s = 0; s < 5; s++) { x += Math.random() * 40 - 20; y += 52; g.lineTo(x, y); } g.stroke(); }
        g.fillStyle = 'rgba(255,255,255,0.14)'; for (let i = 0; i < 40; i++) g.fillRect(Math.random() * 256, Math.random() * 256, 3, 3);
    } else if (theme.wallTex === 'sandstone') {
        _blockWall(g, ['#dcc088', '#d0b076', '#e0c894', '#cba86e'], '#8a6f4a', _speckle('#b89a68'));
        g.fillStyle = hexToCss(theme.accent, 0.4); g.fillRect(0, 214, 256, 6);
    } else if (theme.wallTex === 'marble') {
        _blockWall(g, ['#ece4d2', '#e4dbc6', '#f0e8d8', '#dfd6c0'], '#c9bfa8', _marbleVeins);
    } else if (theme.wallTex === 'redrock') {
        _blockWall(g, ['#b0623a', '#a25631', '#bd6e42', '#98502e'], '#6f3a22', _redStrata);
    } else if (theme.wallTex === 'basalt') {
        _blockWall(g, ['#2e2a33', '#262230', '#332e3a', '#221e2a'], '#15121a', null);
        g.strokeStyle = 'rgba(255,110,30,0.85)'; g.lineWidth = 2; // glowing lava seams
        for (let i = 0; i < 6; i++) { let x = Math.random() * 256, y = Math.random() * 256; g.beginPath(); g.moveTo(x, y); for (let s = 0; s < 4; s++) { x += Math.random() * 50 - 25; y += Math.random() * 50 - 25; g.lineTo(x, y); } g.stroke(); }
        g.fillStyle = 'rgba(255,170,60,0.7)'; for (let i = 0; i < 22; i++) g.fillRect(Math.random() * 256, Math.random() * 256, 3, 3);
    } else if (theme.wallTex === 'mossstone') {
        _blockWall(g, ['#8f9878', '#849072', '#98a082', '#7c886c'], '#4a5240', _speckle('#6a7452'));
        g.fillStyle = 'rgba(70,110,50,0.4)';
        for (let i = 0; i < 10; i++) { g.beginPath(); g.ellipse(Math.random() * 256, Math.random() * 256, 10 + Math.random() * 14, 6 + Math.random() * 8, Math.random() * 3, 0, 6.283); g.fill(); }
    } else if (theme.wallTex === 'cloudmarble') {
        _blockWall(g, ['#f4eee0', '#efe8d8', '#f6f0e4', '#eae2d2'], '#d8cfba', (g, bx, by, bw, bh) => { g.strokeStyle = 'rgba(200,165,80,0.35)'; g.lineWidth = 1; g.beginPath(); g.moveTo(bx + Math.random() * bw, by); g.lineTo(bx + Math.random() * bw, by + bh); g.stroke(); });
    } else if (theme.wallTex === 'coralstone') {
        _blockWall(g, ['#e8b09a', '#dfa088', '#eeb8a2', '#d89680'], '#b07a68', _speckle('#c98a76'));
        g.fillStyle = 'rgba(150,90,75,0.3)';
        for (let i = 0; i < 40; i++) { g.beginPath(); g.arc(Math.random() * 256, Math.random() * 256, 1.5 + Math.random() * 2, 0, 6.283); g.fill(); }
    } else { // ashlar granite
        _blockWall(g, ['#9aa0a8', '#8f959e', '#a2a8b0', '#888e97'], '#5c626c', _speckle('#7a808a'));
        g.fillStyle = hexToCss(theme.accent, 0.45); g.fillRect(0, 214, 256, 6);
    }
    const t = _tex(g.canvas, true);
    wallTextureCache[theme.id] = t;
    return t;
}
